css:
/* Plinth — a device frame that morphs while its site reflows by container queries.
   Re-theme: --bkw-morph-bg, -ink, -accent, -device. */
.bkw-morph {
  --bkw-morph-bg: oklch(0.985 0.004 95);
  --bkw-morph-ink: oklch(0.22 0.012 260);
  --bkw-morph-accent: oklch(0.62 0.19 38);
  --bkw-morph-device: oklch(0.23 0.008 260);
  --bkw-morph-line: color-mix(in oklch, var(--bkw-morph-ink) 11%, var(--bkw-morph-bg));
  --bkw-morph-mute: color-mix(in oklch, var(--bkw-morph-ink) 58%, var(--bkw-morph-bg));
  --bkw-morph-soft: color-mix(in oklch, var(--bkw-morph-ink) 4%, var(--bkw-morph-bg));
  --bkw-morph-spring: linear(0, 0.027, 0.092, 0.179, 0.281, 0.383, 0.485, 0.582, 0.666, 0.742, 0.806, 0.861, 0.905, 0.94, 0.968, 0.988, 1.003, 1.013, 1.019, 1.023, 1.024, 1.024, 1.023, 1.021, 1.018, 1.016, 1.013, 1.011, 1.009, 1.007, 1.005, 1.004, 1.003, 1.002, 1.001, 1, 1);
  --bkw-morph-out: cubic-bezier(.2, .8, .2, 1);

  container-type: inline-size;
  container-name: bkw-morph;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  border-radius: 24px;
  background: var(--bkw-morph-bg);
  color: var(--bkw-morph-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  overflow: hidden;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkw-morph-accent); outline-offset: 3px; border-radius: 8px; }
}
.bkw-morph__in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "copy" "stage";
  gap: 28px;
  padding: clamp(20px, 4.5cqi, 56px);
}
.bkw-morph__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- copy ---------- */
.bkw-morph__copy { grid-area: copy; display: flex; flex-direction: column; align-items: flex-start; min-width: 0; }
.bkw-morph__brand {
  display: inline-flex; align-items: center; gap: 8px; font-weight: 700; font-size: 16px; letter-spacing: -.01em;
  & svg { width: 24px; height: 24px; fill: none; stroke: var(--bkw-morph-accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.bkw-morph__eyebrow {
  margin: clamp(22px, 4cqi, 40px) 0 12px; font-size: 12px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase;
  color: var(--bkw-morph-accent);
}
.bkw-morph__title {
  margin: 0; max-width: 15ch;
  font-size: clamp(1.95rem, 1.1rem + 3.4cqi, 3.15rem); line-height: 1.02; letter-spacing: -.04em; font-weight: 720;
  text-wrap: balance;
}
.bkw-morph__lede { margin: 16px 0 0; max-width: 44ch; font-size: clamp(15px, 14px + .25cqi, 17px); line-height: 1.55; color: var(--bkw-morph-mute); text-wrap: pretty; }

/* segmented radios — the thumb is placed by :has() */
.bkw-morph__seg {
  position: relative; margin: 26px 0 0; padding: 4px; border: 0; min-width: 0; width: min(100%, 360px);
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  border-radius: 14px; background: color-mix(in oklch, var(--bkw-morph-ink) 6%, var(--bkw-morph-bg));
  & label {
    position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; gap: 7px;
    padding: 10px 6px; border-radius: 10px; font-size: 13.5px; font-weight: 600; cursor: pointer;
    color: var(--bkw-morph-mute); transition: color .3s var(--bkw-morph-out);
  }
  & label:hover { color: var(--bkw-morph-ink); }
  & label:has(:checked) { color: var(--bkw-morph-ink); }
  & label:has(:focus-visible) { outline: 2px solid var(--bkw-morph-accent); outline-offset: 1px; }
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
  & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.bkw-morph__thumb {
  position: absolute; top: 4px; left: 4px; bottom: 4px; width: calc((100% - 8px) / 3);
  border-radius: 10px; background: var(--bkw-morph-bg);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--bkw-morph-ink) 14%, transparent), 0 6px 16px -8px color-mix(in oklch, var(--bkw-morph-ink) 30%, transparent);
  transition: translate .55s var(--bkw-morph-spring);
}
.bkw-morph__seg:has([value="tablet"]:checked) .bkw-morph__thumb { translate: 100% 0; }
.bkw-morph__seg:has([value="phone"]:checked) .bkw-morph__thumb { translate: 200% 0; }

/* width meter */
.bkw-morph__meter { margin-top: 22px; width: min(100%, 360px); }
.bkw-morph__read {
  display: flex; align-items: baseline; gap: 10px; font-size: 12.5px; color: var(--bkw-morph-mute);
  & b { font: 650 22px/1 ui-monospace, Menlo, monospace; color: var(--bkw-morph-ink); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & small { font-size: 12px; margin-left: 2px; color: var(--bkw-morph-mute); font-weight: 500; }
}
.bkw-morph__lay {
  margin-left: auto; padding: 3px 9px; border-radius: 999px; font-weight: 650; color: var(--bkw-morph-ink);
  background: color-mix(in oklch, var(--bkw-morph-accent) 14%, var(--bkw-morph-bg));
}
.bkw-morph__ruler {
  --x: .889;
  position: relative; height: 26px; margin-top: 12px; display: block; container-type: inline-size;
  border-radius: 7px; background: var(--bkw-morph-soft); border: 1px solid var(--bkw-morph-line);
}
.bkw-morph__zone {
  position: absolute; top: 0; bottom: 0; left: calc(var(--a) * 100%); width: calc((var(--z) - var(--a)) * 100%);
  display: grid; place-items: center; font: 600 10.5px/1 ui-monospace, Menlo, monospace; font-style: normal; color: var(--bkw-morph-mute);
  transition: color .3s, background-color .3s;
  & + & { border-left: 1px dashed color-mix(in oklch, var(--bkw-morph-ink) 22%, transparent); }
}
.bkw-morph[data-layout="1"] .bkw-morph__zone:nth-of-type(1),
.bkw-morph[data-layout="2"] .bkw-morph__zone:nth-of-type(2),
.bkw-morph[data-layout="4"] .bkw-morph__zone:nth-of-type(3) { color: var(--bkw-morph-ink); background: color-mix(in oklch, var(--bkw-morph-accent) 10%, transparent); }
.bkw-morph__mark {
  position: absolute; top: -5px; bottom: -5px; left: 0; width: 2px; border-radius: 2px;
  background: var(--bkw-morph-accent);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkw-morph-accent) 22%, transparent);
  translate: calc(var(--x) * (100cqi - 2px)) 0;
}
.bkw-morph__ticks {
  position: relative; height: 16px; margin-top: 5px; font: 500 10.5px/16px ui-monospace, Menlo, monospace; color: var(--bkw-morph-mute); font-variant-numeric: tabular-nums;
  & span { position: absolute; left: calc(var(--a, 0) * 100%); translate: -50% 0; }
  & span:first-child { translate: 0 0; }
  & span:last-child { left: auto; right: 0; translate: 0 0; }
}
.bkw-morph__fine { margin: 14px 0 0; font-size: 13px; color: var(--bkw-morph-mute); & b { color: var(--bkw-morph-ink); font-variant-numeric: tabular-nums; } }

/* ---------- stage + morphing device ---------- */
.bkw-morph__stage {
  grid-area: stage; position: relative; min-width: 0; height: 450px; border-radius: 20px;
  background:
    radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--bkw-morph-ink) 13%, transparent) 1px, transparent 1.5px) 0 0 / 18px 18px,
    radial-gradient(70% 60% at 50% 55%, color-mix(in oklch, var(--bkw-morph-accent) 7%, var(--bkw-morph-bg)), var(--bkw-morph-soft));
  border: 1px solid var(--bkw-morph-line);
  overflow: hidden;
}
.bkw-morph__dev {
  --b: 0; --c: 40; --r: 14;
  position: absolute; left: 50%; top: 50%;
  translate: -50% -50%;
  scale: var(--k);
  padding: calc(var(--b) * 1px);
  border-radius: calc(var(--r) * 1px);
  background: var(--bkw-morph-device);
  box-shadow:
    0 0 0 1px color-mix(in oklch, var(--bkw-morph-device), white 14%) inset,
    0 40px 80px -30px color-mix(in oklch, var(--bkw-morph-ink) 55%, transparent),
    0 12px 24px -12px color-mix(in oklch, var(--bkw-morph-ink) 40%, transparent);
  transition: scale .8s var(--bkw-morph-spring), padding .8s var(--bkw-morph-spring), border-radius .8s var(--bkw-morph-spring), opacity .6s var(--bkw-morph-out), filter .6s var(--bkw-morph-out);
  @starting-style { opacity: 0; filter: blur(8px); }
}
.bkw-morph:has([value="tablet"]:checked) .bkw-morph__dev { --b: 18; --c: 0; --r: 40; }
.bkw-morph:has([value="phone"]:checked) .bkw-morph__dev { --b: 12; --c: 0; --r: 56; }

.bkw-morph__chrome {
  display: flex; align-items: center; gap: 16px; height: calc(var(--c) * 1px); padding-inline: 16px; overflow: hidden;
  opacity: calc(var(--c) / 40);
  transition: height .8s var(--bkw-morph-spring), opacity .4s var(--bkw-morph-out);
}
.bkw-morph__dots { display: flex; gap: 7px; & i { width: 11px; height: 11px; border-radius: 50%; background: color-mix(in oklch, var(--bkw-morph-device), white 22%); } }
.bkw-morph__url {
  flex: 0 1 340px; margin-inline: auto; display: flex; align-items: center; justify-content: center; gap: 6px; height: 24px; border-radius: 8px;
  font: 500 12.5px/1 system-ui, sans-serif; color: color-mix(in oklch, var(--bkw-morph-device), white 62%);
  background: color-mix(in oklch, var(--bkw-morph-device), white 9%);
  & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; }
}
.bkw-morph__screen {
  container: bkw-morph-site / inline-size;
  position: relative;
  width: calc(var(--w) * 1px);
  height: calc(var(--h) * 1px);
  --rt: calc((var(--r) - var(--b)) * 1px * (1 - var(--c) / 40));
  --rb: calc((var(--r) - var(--b)) * 1px);
  border-radius: var(--rt) var(--rt) var(--rb) var(--rb);
  overflow: hidden;
  background: oklch(0.975 0.012 80);
  transition: width .8s var(--bkw-morph-spring), height .8s var(--bkw-morph-spring), border-radius .8s var(--bkw-morph-spring);
}
.bkw-morph__dev.is-drag .bkw-morph__screen { transition: height .8s var(--bkw-morph-spring), border-radius .8s var(--bkw-morph-spring); }
.bkw-morph__notch {
  position: absolute; z-index: 3; top: 12px; left: 50%; width: 96px; height: 28px; translate: -50% 0; border-radius: 99px;
  background: var(--bkw-morph-device); opacity: 0; scale: .6; transition: opacity .3s, scale .5s var(--bkw-morph-spring);
}
.bkw-morph:has([value="phone"]:checked) .bkw-morph__notch { opacity: 1; scale: 1; transition-delay: .25s; }

.bkw-morph__grip {
  position: absolute; z-index: 4; top: 50%; right: -26px; width: 40px; height: 120px; translate: 0 -50%;
  display: grid; place-items: center; cursor: ew-resize; touch-action: none; border-radius: 20px;
  & i { width: 10px; height: 84px; border-radius: 10px; background: var(--bkw-morph-bg); border: 2px solid color-mix(in oklch, var(--bkw-morph-ink) 30%, var(--bkw-morph-bg));
        box-shadow: 0 6px 16px -6px color-mix(in oklch, var(--bkw-morph-ink) 50%, transparent); transition: background-color .2s, border-color .2s, scale .3s var(--bkw-morph-spring); }
  &:hover i, &:focus-visible i, .bkw-morph__dev.is-drag & i { background: var(--bkw-morph-accent); border-color: var(--bkw-morph-accent); scale: 1.15 1.05; }
  &:focus-visible { outline-width: 5px; outline-offset: 0; }
}

/* ---------- the mini site (responds to its own screen, not the page) ---------- */
.bkw-morph__site {
  --sink: oklch(0.27 0.03 55);
  --sclay: oklch(0.6 0.12 40);
  height: 100%; overflow-y: auto; scrollbar-width: none; overscroll-behavior: contain;
  color: var(--sink); font-size: 15px;
}
.bkw-morph__nav {
  position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 24px; padding: 18px 28px;
  background: color-mix(in oklch, oklch(0.975 0.012 80) 96%, transparent);
  border-bottom: 1px solid color-mix(in oklch, var(--sink) 10%, transparent);
}
.bkw-morph__logo { display: flex; align-items: center; gap: 7px; font: 700 21px/1 ui-serif, Georgia, serif; letter-spacing: -.02em;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--sclay); stroke-width: 2; } }
.bkw-morph__links { display: flex; gap: 22px; margin-left: auto; font-size: 14px; & a:hover { color: var(--sclay); }
  & a[aria-current="page"] { color: var(--sclay); text-decoration: underline 2px; text-underline-offset: 7px; } }
.bkw-morph__bag { display: inline-flex; align-items: center; gap: 7px; padding: 7px 13px; border-radius: 99px; border: 1px solid color-mix(in oklch, var(--sink) 18%, transparent); font-size: 13.5px; font-weight: 600; }
.bkw-morph__count { display: inline-grid; place-items: center; min-width: 21px; height: 21px; padding-inline: 5px; border-radius: 99px; background: var(--sink); color: oklch(0.975 0.012 80); font-size: 12px; font-variant-numeric: tabular-nums; }
.bkw-morph__count.is-bump { animation: bkw-morph-bump .5s var(--bkw-morph-spring); }
@keyframes bkw-morph-sheet { from { opacity: 0; translate: 0 -6px; } }
@keyframes bkw-morph-bump { 0% { scale: 1; } 30% { scale: 1.45; background: var(--sclay); } 100% { scale: 1; } }
.bkw-morph__burger { display: none; width: 34px; height: 34px; padding: 0; border-radius: 10px; place-content: center; gap: 5px; border: 1px solid color-mix(in oklch, var(--sink) 18%, transparent);
  background: transparent; color: inherit; cursor: pointer;
  & i { display: block; width: 15px; height: 2px; border-radius: 2px; background: currentColor; transition: translate .3s var(--bkw-morph-out), rotate .3s var(--bkw-morph-out); }
  &[aria-expanded="true"] i:first-child { translate: 0 3.5px; rotate: 45deg; }
  &[aria-expanded="true"] i:last-child { translate: 0 -3.5px; rotate: -45deg; } }

.bkw-morph__hero { display: grid; grid-template-columns: 1fr 1fr; grid-template-areas: "text img"; gap: 30px; align-items: center; padding: 34px 28px 28px; }
.bkw-morph__htext { grid-area: text; & h3 { margin: 0; font: 600 44px/1.02 ui-serif, Georgia, serif; letter-spacing: -.025em; text-wrap: balance; }
  & p { margin: 14px 0 0; line-height: 1.5; color: color-mix(in oklch, var(--sink) 72%, transparent); text-wrap: pretty; max-width: 36ch; }
  & .bkw-morph__kick { margin: 0 0 12px; font-size: 11.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--sclay); } }
.bkw-morph__shop { display: inline-block; margin-top: 20px; padding: 12px 20px; border-radius: 99px; background: var(--sink); color: oklch(0.975 0.012 80); font-weight: 600; font-size: 14px; }
.bkw-morph__himg { grid-area: img; aspect-ratio: 16 / 11; border-radius: 16px; overflow: hidden; & svg { display: block; width: 100%; height: 100%; } }

.bkw-morph__grid { list-style: none; margin: 0; padding: 4px 28px 22px; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.bkw-morph__p {
  position: relative; display: grid; grid-template-columns: 1fr auto; grid-template-areas: "img img" "meta price";
  gap: 10px 8px;
}
.bkw-morph__pimg {
  grid-area: img; aspect-ratio: 1; border-radius: 14px; display: grid; place-items: center;
  background: color-mix(in oklch, var(--g) 22%, oklch(0.95 0.015 80));
  & svg { width: 76%; height: 76%; }
  & .g { fill: var(--g); } & .t { fill: var(--t); } & .f { fill: color-mix(in oklch, var(--t), black 10%); }
  & .h { fill: none; stroke: var(--g); stroke-width: 5; }
  & svg { transition: translate .5s var(--bkw-morph-spring), rotate .5s var(--bkw-morph-spring); }
}
.bkw-morph__p:hover .bkw-morph__pimg svg { translate: 0 -4%; rotate: -3deg; }
.bkw-morph__pmeta { grid-area: meta; display: grid; gap: 2px; min-width: 0; & b { font-size: 14.5px; } & span { font-size: 12.5px; color: color-mix(in oklch, var(--sink) 60%, transparent); } }
.bkw-morph__price { grid-area: price; font-weight: 650; font-variant-numeric: tabular-nums; }
.bkw-morph__add {
  position: absolute; top: 10px; right: 10px; width: 34px; height: 34px; border-radius: 50%; border: 0; display: grid; place-items: center; cursor: pointer;
  background: oklch(0.99 0.005 80); color: var(--sink); box-shadow: 0 4px 12px -4px color-mix(in oklch, var(--sink) 40%, transparent);
  transition: background-color .25s, color .25s, scale .4s var(--bkw-morph-spring), rotate .4s var(--bkw-morph-spring);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }
  &:hover { scale: 1.08; }
  &[aria-pressed="true"] { background: var(--sink); color: oklch(0.975 0.012 80); rotate: 45deg; }
}
/* the other pages of the mini site; a page section is shown by the [data-on] list it belongs to */
.bkw-morph__site [hidden] { display: none; }
.bkw-morph__pg { padding: 34px 28px 28px;
  & h3 { margin: 0; max-width: 18ch; font: 600 40px/1.04 ui-serif, Georgia, serif; letter-spacing: -.025em; text-wrap: balance; }
  & > p { margin: 14px 0 0; max-width: 52ch; line-height: 1.5; color: color-mix(in oklch, var(--sink) 72%, transparent); text-wrap: pretty; }
  & .bkw-morph__kick { margin: 0 0 12px; font-size: 11.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--sclay); } }
.bkw-morph__head { padding-bottom: 22px; }
.bkw-morph__rows { list-style: none; margin: 24px 0 0; padding: 0; border-top: 1px solid color-mix(in oklch, var(--sink) 12%, transparent);
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "name end" "when end"; gap: 3px 16px; align-items: center; padding: 14px 0; border-bottom: 1px solid color-mix(in oklch, var(--sink) 12%, transparent); }
  & b { grid-area: name; font-size: 15px; }
  & span { grid-area: when; font-size: 13px; color: color-mix(in oklch, var(--sink) 60%, transparent); }
  & em { grid-area: end; font-style: normal; font-weight: 650; font-variant-numeric: tabular-nums; } }
.bkw-morph__strip { margin: 0; padding: 14px 28px 26px; font-size: 13px; color: color-mix(in oklch, var(--sink) 62%, transparent); border-top: 1px solid color-mix(in oklch, var(--sink) 10%, transparent); }

/* tablet-sized screen */
@container bkw-morph-site (max-width: 759.98px) {
  .bkw-morph__hero { grid-template-columns: 1fr; grid-template-areas: "img" "text"; gap: 22px; }
  .bkw-morph__himg { aspect-ratio: 16 / 8; }
  .bkw-morph__htext h3 { font-size: 40px; }
  .bkw-morph__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkw-morph__pg h3 { font-size: 34px; }
}
/* phone-sized screen */
@container bkw-morph-site (max-width: 479.98px) {
  .bkw-morph__nav { padding: 52px 18px 14px; gap: 12px; }
  .bkw-morph__links { display: none; }
  .bkw-morph__bag { margin-left: auto; }
  .bkw-morph__burger { display: grid; }
  .bkw-morph__nav.is-menu .bkw-morph__links {
    position: absolute; top: 100%; left: 0; right: 0; display: flex; flex-direction: column; gap: 0; margin: 0; padding: 4px 18px 10px; font-size: 16px;
    background: oklch(0.975 0.012 80); border-bottom: 1px solid color-mix(in oklch, var(--sink) 10%, transparent);
    box-shadow: 0 18px 24px -18px color-mix(in oklch, var(--sink) 40%, transparent);
    animation: bkw-morph-sheet .3s var(--bkw-morph-out);
    & a { padding: 13px 0; } & a + a { border-top: 1px solid color-mix(in oklch, var(--sink) 8%, transparent); }
  }
  .bkw-morph__pg { padding: 22px 18px; & h3 { font-size: 29px; } }
  .bkw-morph__hero { padding: 20px 18px; }
  .bkw-morph__himg { aspect-ratio: 4 / 3; }
  .bkw-morph__htext h3 { font-size: 34px; }
  .bkw-morph__grid { grid-template-columns: 1fr; padding-inline: 18px; gap: 10px; }
  .bkw-morph__p { grid-template-columns: 76px 1fr auto; grid-template-areas: "img meta price"; align-items: center; gap: 14px; padding: 8px; border-radius: 16px; background: oklch(0.99 0.006 80); }
  .bkw-morph__add { position: static; grid-column: 3; grid-row: 1; display: none; }
  .bkw-morph__strip { padding-inline: 18px; }
}

/* ---------- section layout ---------- */
@container bkw-morph (min-width: 820px) {
  .bkw-morph__in { grid-template-columns: minmax(300px, .8fr) minmax(0, 1.25fr); grid-template-areas: "copy stage"; gap: clamp(28px, 4cqi, 56px); align-items: center; }
  .bkw-morph__stage { height: 560px; }
}
@container bkw-morph (max-width: 479.98px) {
  .bkw-morph__seg label span { font-size: 12.5px; }
  .bkw-morph__seg label { gap: 5px; padding-inline: 4px; }
  .bkw-morph__stage { height: 430px; margin-inline: -6px; }
  .bkw-morph__grip { right: -30px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-morph .bkw-morph__dev, .bkw-morph .bkw-morph__screen, .bkw-morph .bkw-morph__chrome,
  .bkw-morph .bkw-morph__thumb, .bkw-morph .bkw-morph__notch, .bkw-morph .bkw-morph__add,
  .bkw-morph .bkw-morph__pimg svg, .bkw-morph .bkw-morph__grip i { transition: none; }
  .bkw-morph .bkw-morph__count.is-bump, .bkw-morph .bkw-morph__nav.is-menu .bkw-morph__links { animation: none; }
  .bkw-morph .bkw-morph__burger i { transition: none; }
  .bkw-morph .bkw-morph__p:hover .bkw-morph__pimg svg { translate: none; rotate: none; }
}

