// Plinth device morph. The site inside the frame has fixed "virtual" pixel sizes so its
// container queries see real phone/tablet/desktop widths; the whole frame is then scaled
// to fit the stage. Dragging the screen edge changes only the virtual width.
const dev = root.querySelector(".bkw-morph__dev");
const screen = root.querySelector(".bkw-morph__screen");
const stage = root.querySelector(".bkw-morph__stage");
const grip = root.querySelector(".bkw-morph__grip");
const radios = Array.from(root.querySelectorAll(".bkw-morph__seg input"));
const outW = root.querySelector(".bkw-morph__w");
const outLay = root.querySelector(".bkw-morph__lay");
const ruler = root.querySelector(".bkw-morph__ruler");
const count = root.querySelector(".bkw-morph__count");

const uid = Math.random().toString(36).slice(2, 8);
radios.forEach((r) => { r.name = "bkw-morph-device-" + uid; });

const PRESET = {
  desktop: { w: 960, h: 600, b: 0, c: 40 },
  tablet: { w: 620, h: 820, b: 18, c: 0 },
  phone: { w: 360, h: 740, b: 12, c: 0 }
};
const MIN = 320, MAX = 1040, PAD = 36;
const state = { dev: "desktop", w: 960, h: 600, k: 0.6 };

const classify = (w) => (w < 480 ? "phone" : w < 760 ? "tablet" : "desktop");
const layoutOf = (w) => (w < 480 ? ["1", "1-up list"] : w < 760 ? ["2", "2-up grid"] : ["4", "4-up grid"]);

function fit() {
  const p = PRESET[state.dev];
  const sw = stage.clientWidth - PAD, sh = stage.clientHeight - PAD;
  if (sw <= 0 || sh <= 0) return;
  state.k = Math.min(1, sw / (state.w + 2 * p.b), sh / (state.h + 2 * p.b + p.c));
  dev.style.setProperty("--k", state.k.toFixed(4));
}
function setSize(w, h) {
  state.w = w; state.h = h;
  dev.style.setProperty("--w", w);
  dev.style.setProperty("--h", h);
  grip.setAttribute("aria-valuenow", String(w));
  grip.setAttribute("aria-valuetext", w + " pixels, " + layoutOf(w)[1]);
}
function check(name) {
  const r = radios.find((x) => x.value === name);
  if (r && !r.checked) r.checked = true;
}
function choose(name) {
  state.dev = name;
  check(name);
  setSize(PRESET[name].w, PRESET[name].h);
  fit();
}
function resizeTo(w) {
  w = Math.max(MIN, Math.min(MAX, Math.round(w)));
  const d = classify(w);
  let h = state.h;
  if (d !== state.dev) { state.dev = d; check(d); h = PRESET[d].h; }
  setSize(w, h);
}
radios.forEach((r) => r.addEventListener("change", () => { if (r.checked) choose(r.value); }));

// drag the screen edge: the frame is centred, so the edge moves half as far as the width grows
let drag = null;
grip.addEventListener("pointerdown", (e) => {
  if (e.button !== 0) return;
  e.preventDefault();
  grip.setPointerCapture(e.pointerId);
  grip.focus({ preventScroll: true });
  drag = { x: e.clientX, w: state.w, k: state.k };
  dev.classList.add("is-drag");
});
grip.addEventListener("pointermove", (e) => {
  if (!drag) return;
  const room = Math.floor((stage.clientWidth - PAD) / drag.k - 2 * PRESET[state.dev].b);
  resizeTo(Math.min(room, drag.w + (2 * (e.clientX - drag.x)) / drag.k));
});
const endDrag = () => {
  if (!drag) return;
  drag = null;
  dev.classList.remove("is-drag");
  fit();
};
grip.addEventListener("pointerup", endDrag);
grip.addEventListener("pointercancel", endDrag);
grip.addEventListener("lostpointercapture", endDrag);
grip.addEventListener("keydown", (e) => {
  const step = e.shiftKey ? 80 : 20;
  let w = state.w;
  if (e.key === "ArrowRight" || e.key === "ArrowUp") w += step;
  else if (e.key === "ArrowLeft" || e.key === "ArrowDown") w -= step;
  else if (e.key === "PageUp") w += 160;
  else if (e.key === "PageDown") w -= 160;
  else if (e.key === "Home") w = MIN;
  else if (e.key === "End") w = MAX;
  else return;
  e.preventDefault();
  resizeTo(w);
  fit();
});

// the readout follows the screen's real layout width, frame by frame, while it springs
const ro = new ResizeObserver((entries) => {
  if (!root.isConnected) { ro.disconnect(); return; }
  for (const en of entries) {
    if (en.target === stage) { if (!drag) fit(); continue; }
    const w = Math.round(en.contentRect.width);
    const [n, label] = layoutOf(w);
    outW.textContent = String(w);
    if (root.dataset.layout !== n) {
      root.dataset.layout = n; outLay.textContent = label;
      if (n !== "1" && nav.classList.contains("is-menu")) menu(false);
    }
    ruler.style.setProperty("--x", ((Math.min(MAX, Math.max(MIN, w)) - MIN) / (MAX - MIN)).toFixed(4));
  }
});
ro.observe(screen);
ro.observe(stage);

// the shop inside is live: adding a pot fills the bag
let bag = 2;
root.querySelectorAll(".bkw-morph__add").forEach((b) => {
  b.setAttribute("aria-pressed", "false");
  b.addEventListener("click", () => {
    const on = b.getAttribute("aria-pressed") !== "true";
    b.setAttribute("aria-pressed", String(on));
    bag += on ? 1 : -1;
    count.textContent = String(bag);
    count.classList.remove("is-bump");
    void count.offsetWidth;
    count.classList.add("is-bump");
  });
});

// the shop inside is a small site of its own: its links switch pages, the address bar follows
const site = root.querySelector(".bkw-morph__site");
const nav = root.querySelector(".bkw-morph__nav");
const links = root.querySelector(".bkw-morph__links");
const burger = root.querySelector(".bkw-morph__burger");
const addr = root.querySelector(".bkw-morph__addr");
const sections = Array.from(site.querySelectorAll("[data-on]"));
const navLinks = [root.querySelector(".bkw-morph__logo"), ...links.querySelectorAll("a")];
const HOST = addr.textContent;
const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
let page = "home";
links.id = "bkw-morph-links-" + uid;
burger.setAttribute("aria-controls", links.id);

function menu(open) {
  nav.classList.toggle("is-menu", open);
  burger.setAttribute("aria-expanded", String(open));
  burger.setAttribute("aria-label", open ? "Close menu" : "Menu");
}
function go(next, from) {
  menu(false);
  if (next === page) { site.scrollTo({ top: 0, behavior: still ? "auto" : "smooth" }); return; }
  page = next;
  sections.forEach((s) => {
    const on = s.dataset.on.split(" ").includes(next);
    const enter = on && s.hidden;
    s.hidden = !on;
    if (enter && !still) s.animate([{ opacity: 0, transform: "translateY(10px)" }, { opacity: 1, transform: "none" }], { duration: 420, easing: "cubic-bezier(.2, .8, .2, 1)" });
  });
  navLinks.forEach((a) => { if (a.dataset.page === next) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current"); });
  addr.textContent = HOST + (next === "home" ? "" : "/" + next);
  site.scrollTop = 0;
  // the link that was used may be gone now (the hero button, a link in the closed menu): focus the new page
  if (from && !from.getClientRects().length) {
    const h = site.querySelector('[data-on~="' + next + '"] h3');
    if (h) h.focus({ preventScroll: true });
  }
}
site.addEventListener("click", (e) => {
  const a = e.target.closest("a[data-page]");
  if (a) { e.preventDefault(); go(a.dataset.page, a); return; }
  if (nav.classList.contains("is-menu") && !nav.contains(e.target)) menu(false);
});
burger.addEventListener("click", () => menu(burger.getAttribute("aria-expanded") !== "true"));
nav.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && nav.classList.contains("is-menu")) { menu(false); burger.focus(); }
});

// a narrow stage opens on the phone, where the shop is legible at its natural scale
if (stage.clientWidth < 520) choose("phone");
else { setSize(state.w, state.h); fit(); }

