/* Quell — a spectrogram before/after. Re-theme: --bkw-compare-bg, -ink, -accent, -cool, -warn.
   The canvas colormap is read back from these tokens at runtime. */
@property --bkw-compare-p { syntax: "<number>"; inherits: true; initial-value: .5; }

.bkw-compare {
  --bkw-compare-bg: oklch(0.17 0.012 250);
  --bkw-compare-ink: oklch(0.95 0.008 110);
  --bkw-compare-accent: oklch(0.9 0.19 124);
  --bkw-compare-cool: oklch(0.45 0.085 210);
  --bkw-compare-warn: oklch(0.74 0.16 35);
  --bkw-compare-panel: color-mix(in oklch, var(--bkw-compare-bg), var(--bkw-compare-ink) 5%);
  --bkw-compare-line: color-mix(in oklch, var(--bkw-compare-ink) 13%, transparent);
  --bkw-compare-mute: color-mix(in oklch, var(--bkw-compare-ink) 58%, var(--bkw-compare-bg));
  --bkw-compare-spring: linear(0, 0.034, 0.118, 0.231, 0.353, 0.48, 0.599, 0.705, 0.794, 0.869, 0.929, 0.973, 1.006, 1.028, 1.041, 1.048, 1.049, 1.047, 1.043, 1.037, 1.031, 1.025, 1.019, 1.014, 1.01, 1.006, 1.003, 1.001, 1, 0.999, 0.998, 0.998, 0.998, 0.998, 0.998, 0.998, 1);
  --bkw-compare-out: cubic-bezier(.16, 1, .3, 1);

  container-type: inline-size;
  container-name: bkw-compare;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  border-radius: 24px;
  overflow: hidden;
  color: var(--bkw-compare-ink);
  background:
    radial-gradient(80% 60% at 85% 0%, color-mix(in oklch, var(--bkw-compare-cool) 22%, transparent), transparent 70%),
    var(--bkw-compare-bg);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkw-compare-accent); outline-offset: 3px; border-radius: 6px; }
}
.bkw-compare__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkw-compare__in {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "head" "fig" "stats";
  gap: 26px;
  padding: clamp(20px, 4.4cqi, 54px);
}

.bkw-compare__head { grid-area: head; min-width: 0; }
.bkw-compare__brand {
  display: inline-flex; align-items: center; gap: 9px; font-weight: 700; font-size: 16px; letter-spacing: .01em;
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkw-compare-accent); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.bkw-compare__eyebrow { margin: 26px 0 10px; font: 600 12px/1.3 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase; color: var(--bkw-compare-accent); }
.bkw-compare__title { margin: 0; max-width: 17ch; font-size: clamp(1.9rem, 1.1rem + 3cqi, 3rem); line-height: 1.03; letter-spacing: -.035em; font-weight: 680; text-wrap: balance; }
.bkw-compare__lede { margin: 16px 0 0; max-width: 56ch; font-size: clamp(14.5px, 13.8px + .25cqi, 16.5px); line-height: 1.6; color: var(--bkw-compare-mute); text-wrap: pretty; & i { color: var(--bkw-compare-ink); } }

/* stats */
.bkw-compare__stats { grid-area: stats; margin: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; border-radius: 16px; overflow: hidden; background: var(--bkw-compare-line); border: 1px solid var(--bkw-compare-line); }
.bkw-compare__stat {
  padding: 14px 16px 15px; background: var(--bkw-compare-panel); min-width: 0;
  & dt { font-size: 12.5px; color: var(--bkw-compare-mute); }
  & dd { margin: 8px 0 0; display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 8px; font-family: ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
  & s { font-size: 13px; color: color-mix(in oklch, var(--bkw-compare-warn) 80%, var(--bkw-compare-bg)); text-decoration-thickness: 1px; }
  & b { font-size: clamp(22px, 18px + .8cqi, 28px); font-weight: 600; letter-spacing: -.03em; color: var(--bkw-compare-accent); display: inline-block; transition: color .3s, translate .5s var(--bkw-compare-spring), opacity .3s; }
  & small { font-size: 12px; color: var(--bkw-compare-mute); }
  &[data-off] b { color: var(--bkw-compare-mute); }
  &[data-off] s { opacity: 0; }
  & b.is-flip { animation: bkw-compare-flip .45s var(--bkw-compare-out); }
}
@keyframes bkw-compare-flip { from { translate: 0 .35em; opacity: 0; filter: blur(3px); } }

/* figure */
.bkw-compare__fig { grid-area: fig; margin: 0; min-width: 0; }
.bkw-compare__bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 18px; margin-bottom: 12px; }
.bkw-compare__file { margin: 0; display: grid; gap: 2px; font: 12px/1.3 ui-monospace, Menlo, monospace; & b { font-weight: 600; font-size: 13px; } & span { color: var(--bkw-compare-mute); } }
.bkw-compare__fixes {
  margin: 0; padding: 0; border: 0; min-width: 0; display: flex; flex-wrap: wrap; gap: 6px;
  & label {
    position: relative; display: inline-flex; align-items: center; gap: 7px; padding: 7px 12px 7px 9px; border-radius: 999px; cursor: pointer;
    font-size: 13px; font-weight: 600; color: var(--bkw-compare-mute); border: 1px solid var(--bkw-compare-line);
    transition: color .2s, background-color .2s, border-color .2s;
  }
  & label:hover { color: var(--bkw-compare-ink); border-color: color-mix(in oklch, var(--bkw-compare-ink) 30%, transparent); }
  & input { appearance: none; margin: 0; width: 14px; height: 14px; border-radius: 4px; border: 1.5px solid currentColor; display: grid; place-items: center; cursor: pointer; transition: background-color .2s, border-color .2s; }
  & input::after { content: ""; width: 7px; height: 4px; border: solid var(--bkw-compare-bg); border-width: 0 0 2px 2px; rotate: -45deg; translate: 0 -1px; scale: 0; transition: scale .3s var(--bkw-compare-spring); }
  & input:checked { background: var(--bkw-compare-accent); border-color: var(--bkw-compare-accent); }
  & input:checked::after { scale: 1; }
  & input:focus-visible { outline: 2px solid var(--bkw-compare-accent); outline-offset: 2px; }
  & label:has(:checked) { color: var(--bkw-compare-ink); background: color-mix(in oklch, var(--bkw-compare-accent) 10%, transparent); border-color: color-mix(in oklch, var(--bkw-compare-accent) 40%, transparent); }
}

.bkw-compare__frame { display: grid; grid-template-columns: 34px minmax(0, 1fr); grid-template-rows: auto auto; grid-template-areas: "y plot" ". x"; column-gap: 8px; }
.bkw-compare__plot {
  grid-area: plot; position: relative; height: 250px; border-radius: 12px; overflow: hidden; container-type: inline-size;
  background: var(--bkw-compare-bg); box-shadow: 0 0 0 1px var(--bkw-compare-line);
  cursor: ew-resize; touch-action: pan-y; user-select: none; -webkit-user-select: none;
  transition: --bkw-compare-p .75s var(--bkw-compare-spring);
}
.bkw-compare__plot.is-drag { transition: none; }
.bkw-compare__cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.bkw-compare__cv--b {
  clip-path: inset(0 0 0 calc(var(--bkw-compare-p) * 100%));
  transition: opacity .35s var(--bkw-compare-out);
  @starting-style { opacity: 0; }
}
.bkw-compare__split {
  position: absolute; top: 0; bottom: 0; left: -22px; width: 44px; display: grid; place-items: center; outline: none;
  translate: calc(var(--bkw-compare-p) * 100cqi) 0;
  &::before { content: ""; position: absolute; top: 0; bottom: 0; left: 21px; width: 2px; background: var(--bkw-compare-ink); box-shadow: 0 0 12px color-mix(in oklch, var(--bkw-compare-bg) 80%, transparent); }
}
.bkw-compare__knob {
  position: relative; width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center;
  background: var(--bkw-compare-ink); color: var(--bkw-compare-bg);
  box-shadow: 0 6px 20px -4px color-mix(in oklch, black 70%, transparent);
  transition: scale .45s var(--bkw-compare-spring), background-color .2s;
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
}
.bkw-compare__plot:hover .bkw-compare__knob, .bkw-compare__plot.is-drag .bkw-compare__knob { scale: 1.1; }
.bkw-compare__split:focus-visible .bkw-compare__knob { background: var(--bkw-compare-accent); box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkw-compare-accent) 35%, transparent); }

.bkw-compare__tag {
  position: absolute; top: 10px; padding: 4px 9px; border-radius: 6px; pointer-events: none;
  font: 600 11px/1.2 ui-monospace, Menlo, monospace; letter-spacing: .06em; text-transform: uppercase;
  background: color-mix(in oklch, var(--bkw-compare-bg) 78%, transparent);
}
.bkw-compare__tag--a { left: 10px; color: var(--bkw-compare-warn); opacity: clamp(0, (var(--bkw-compare-p) - .14) * 9, 1); }
.bkw-compare__tag--b { right: 10px; color: var(--bkw-compare-accent); opacity: clamp(0, (.86 - var(--bkw-compare-p)) * 9, 1); }

/* artefact notes live on the original side: each fades as the split passes it */
.bkw-compare__notes { list-style: none; margin: 0; padding: 0; position: absolute; inset: 0; pointer-events: none; }
.bkw-compare__notes li {
  --x: .1; --y: .5;
  position: absolute; left: calc(var(--x) * 100%); top: calc(var(--y) * 100%);
  display: flex; align-items: center; gap: 6px; white-space: nowrap;
  font: 600 11px/1 ui-monospace, Menlo, monospace; color: var(--bkw-compare-warn);
  opacity: clamp(0, (var(--bkw-compare-p) - var(--x) - .02) * 30, 1);
  translate: -5px -50%;
  &::before { content: ""; width: 9px; height: 9px; flex: none; border-radius: 50%; border: 2px solid currentColor; background: color-mix(in oklch, var(--bkw-compare-bg) 60%, transparent); }
  & span { padding: 3px 6px; border-radius: 4px; background: color-mix(in oklch, var(--bkw-compare-bg) 82%, transparent); }
}
.bkw-compare__notes li[data-flip] { flex-direction: row-reverse; translate: calc(-100% + 5px) -50%; }

.bkw-compare__y, .bkw-compare__x { list-style: none; margin: 0; padding: 0; position: relative; font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: var(--bkw-compare-mute); font-variant-numeric: tabular-nums; }
.bkw-compare__y { grid-area: y; & li { position: absolute; right: 0; top: calc(var(--y) * 100%); translate: 0 -50%; } }
.bkw-compare__x { grid-area: x; height: 22px; display: flex; justify-content: space-between; align-items: end; }
.bkw-compare__cap { margin: 10px 0 0 42px; font-size: 12px; color: var(--bkw-compare-mute); text-wrap: pretty; }

@container bkw-compare (min-width: 640px) {
  .bkw-compare__stats { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .bkw-compare__plot { height: 300px; }
}
@container bkw-compare (min-width: 980px) {
  .bkw-compare__in { grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr); grid-template-areas: "head stats" "fig fig"; column-gap: 56px; align-items: end; }
  .bkw-compare__stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkw-compare__plot { height: 330px; }
}
@container bkw-compare (max-width: 479.98px) {
  .bkw-compare__frame { grid-template-columns: 28px minmax(0, 1fr); column-gap: 6px; }
  .bkw-compare__x li:nth-child(even) { visibility: hidden; }
  .bkw-compare__notes li[data-note="hiss"], .bkw-compare__notes li[data-note="verb"] { display: none; }
  .bkw-compare__cap { margin-left: 34px; }
  .bkw-compare__fixes label { padding: 6px 10px 6px 8px; font-size: 12.5px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-compare .bkw-compare__plot { transition: none; }
  .bkw-compare .bkw-compare__cv--b, .bkw-compare .bkw-compare__knob, .bkw-compare .bkw-compare__fixes input::after { transition: none; }
  .bkw-compare .bkw-compare__stat b.is-flip { animation: none; }
}

js:
// Quell spectrogram before/after. A 12 s two-speaker take is synthesised once — syllables with
// declining pitch, vowel formants and fricatives — then each render adds the room, hiss, hum
// and clicks that the active repairs have not removed. Two DPR-aware canvases are stacked and
// the top one is clipped by a registered --bkw-compare-p.
const plot = root.querySelector(".bkw-compare__plot");
const cvA = root.querySelector(".bkw-compare__cv--a");
const cvB = root.querySelector(".bkw-compare__cv--b");
const split = root.querySelector(".bkw-compare__split");
const boxes = Array.from(root.querySelectorAll(".bkw-compare__fixes input"));
const yAxis = root.querySelector(".bkw-compare__y");
const notes = {};
root.querySelectorAll(".bkw-compare__notes li").forEach((li) => {
  li.innerHTML = "<span>" + li.innerHTML + "</span>";
  notes[li.dataset.note] = li;
});
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

const T = 12, FMIN = 40, FMAX = 12000, LN = Math.log(FMAX / FMIN);
const yOf = (f) => Math.log(FMAX / f) / LN;               // 0 = top (12 kHz), 1 = bottom (40 Hz)

// ---------- the take: deterministic, so the picture is the same on every load ----------
let seed = 41;
const rnd = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
const VOWELS = [[730, 1090, 2440], [270, 2290, 3010], [300, 870, 2240], [530, 1840, 2480], [570, 840, 2410]];
const syl = [], phrases = [];
let t = 0.3, spk = 0;
while (t < T - 0.5) {
  const n = 4 + Math.floor(rnd() * 6), base = spk ? 208 : 116, k = spk ? 1.17 : 1, p0 = t;
  for (let i = 0; i < n && t < T - 0.35; i++) {
    const fr = rnd() < 0.32 ? 0.06 + rnd() * 0.05 : 0;
    const d = 0.11 + rnd() * 0.17;
    const v = VOWELS[Math.floor(rnd() * 5)];
    const decl = 1 - 0.2 * i / n, acc = rnd() < 0.3 ? 1.14 : 1;
    syl.push({
      t0: t + fr, t1: t + fr + d,
      fr: fr ? { t0: t, t1: t + fr, a: 0.35 + rnd() * 0.35 } : null,
      f0a: base * decl * acc, f0b: base * decl * 0.95,
      F: v.map((f) => f * k * (0.94 + rnd() * 0.12)), a: 0.55 + rnd() * 0.45
    });
    t += fr + d + 0.025 + rnd() * 0.06;
  }
  phrases.push([p0, t]);
  t += 0.38 + rnd() * 0.42;
  if (rnd() < 0.75) spk = 1 - spk;
}
const CLICKS = 23, clicks = [];
for (const s of syl) if (clicks.length < CLICKS && rnd() < 0.2) clicks.push(Math.max(0.05, s.t0 - 0.03 - rnd() * 0.05));
while (clicks.length < CLICKS) clicks.push(0.2 + rnd() * (T - 0.4));

// ---------- colormap, read back from the theme tokens ----------
function tokenRGB(name, fallback) {
  const probe = document.createElement("span");
  probe.style.color = "var(" + name + ")";
  probe.style.display = "none";
  root.appendChild(probe);
  const css = getComputedStyle(probe).color;
  probe.remove();
  const c = document.createElement("canvas");
  c.width = c.height = 1;
  const x = c.getContext("2d");
  x.fillStyle = fallback;
  x.fillStyle = css;
  x.fillRect(0, 0, 1, 1);
  const d = x.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}
let LUT;
function buildLUT() {
  const bg = tokenRGB("--bkw-compare-bg", "#14181d"), cool = tokenRGB("--bkw-compare-cool", "#1f5f6b");
  const acc = tokenRGB("--bkw-compare-accent", "#d4f25a"), ink = tokenRGB("--bkw-compare-ink", "#f1f2ea");
  const mix = (a, b, m) => a.map((v, i) => v + (b[i] - v) * m);
  const stops = [[0, bg], [0.32, mix(bg, cool, 0.5)], [0.58, cool], [0.84, acc], [1, mix(acc, ink, 0.8)]];
  LUT = new Uint8ClampedArray(256 * 3);
  for (let i = 0; i < 256; i++) {
    const v = i / 255;
    let j = 0;
    while (j < stops.length - 2 && v > stops[j + 1][0]) j++;
    const [a0, c0] = stops[j], [a1, c1] = stops[j + 1];
    const m = Math.min(1, Math.max(0, (v - a0) / (a1 - a0)));
    const s = m * m * (3 - 2 * m);
    for (let q = 0; q < 3; q++) LUT[i * 3 + q] = c0[q] + (c1[q] - c0[q]) * s;
  }
}

// ---------- synthesis ----------
let NX = 0, NY = 0, dry = null, tex = null, freqs = null, imgA = null, offA = null, offB = null;
function prepare(nx, ny) {
  NX = nx; NY = ny;
  freqs = new Float32Array(NY);
  const step = LN / (NY - 1);
  for (let r = 0; r < NY; r++) freqs[r] = FMAX * Math.exp(-r * step);
  tex = new Float32Array(NX * NY);
  let s2 = 7;
  for (let i = 0; i < tex.length; i++) { s2 = (Math.imul(s2, 1103515245) + 12345) >>> 0; tex[i] = -Math.log((s2 >>> 8) / 16777216 + 1e-7); }
  dry = new Float32Array(NX * NY);
  const SPEECH = 0.022, FRIC = 0.003;
  for (let c = 0; c < NX; c++) {
    const tc = (c + 0.5) / NX * T;
    let amp = 0, f0 = 0, F = null, fa = 0;
    for (const s of syl) {
      if (tc > s.t0 - 0.03 && tc < s.t1 + 0.06) {
        const e = Math.min(1, Math.max(0, (tc - s.t0 + 0.02) / 0.03)) * Math.min(1, Math.max(0, (s.t1 + 0.06 - tc) / 0.08));
        if (e * s.a > amp) { amp = e * s.a; f0 = s.f0a + (s.f0b - s.f0a) * Math.min(1, Math.max(0, (tc - s.t0) / (s.t1 - s.t0))); F = s.F; }
      }
      if (s.fr && tc > s.fr.t0 && tc < s.fr.t1) {
        const m = (tc - s.fr.t0) / (s.fr.t1 - s.fr.t0);
        fa = Math.max(fa, s.fr.a * Math.sin(Math.PI * m));
      }
    }
    if (!amp && !fa) continue;
    for (let r = 0; r < NY; r++) {
      const f = freqs[r];
      let p = 0;
      if (amp) {
        const h = f / f0;
        let comb = 0;
        if (h > 0.6) {
          const fr = h - Math.round(h);
          const blur = Math.min(1, Math.max(0, (f * step / f0 - 0.22) / 0.55));
          comb = Math.exp(-fr * fr / 0.0162) * (1 - blur) + 0.3 * blur;
        }
        let env = 0.035;
        for (let q = 0; q < 3; q++) { const l = Math.log(f / F[q]); env += [1, 0.6, 0.32][q] * Math.exp(-l * l / 0.026); }
        const tilt = f < 280 ? 1 : Math.pow(280 / f, 1.25);
        p = amp * amp * comb * env * tilt * SPEECH;
      }
      if (fa) { const l = Math.log(f / 6200); p += fa * fa * Math.exp(-l * l / 0.22) * FRIC * (0.4 + 0.6 * tex[c * NY + r]); }
      dry[c * NY + r] = p;
    }
  }
}

const HUM = [-24, -32, -27, -38, -31, -42, -36, -46, -41];
function render(fx) {
  const N = NX * NY, P = new Float32Array(N);
  // room: an exponential energy tail per frequency row (RT60 0.62 s, or 0.21 s once repaired)
  const rt = fx.verb ? 0.21 : 0.62, g = fx.verb ? 0.25 : 0.95;
  const a = Math.exp(-(T / NX) * 13.8 / rt);
  for (let r = 0; r < NY; r++) {
    let w = 0;
    const lowBoost = freqs[r] < 400 ? 1.25 : 1;
    for (let c = 0; c < NX; c++) {
      const i = c * NY + r, d = dry[i];
      w = w * a + d * (1 - a) * 3.2;
      P[i] = d + g * w * lowBoost;
    }
  }
  const floor = Math.pow(10, (fx.hiss ? -68 : -41) / 10);
  const clickCols = fx.click ? [] : clicks.map((tt) => Math.round(tt / T * NX - 0.5));
  for (let r = 0; r < NY; r++) {
    const f = freqs[r];
    const hissTilt = 0.55 + 0.9 * Math.log(f / FMIN) / LN;
    let hum = 0;
    if (!fx.hum) for (let k = 1; k <= HUM.length; k++) { const l = Math.log(f / (50 * k)); hum += Math.pow(10, HUM[k - 1] / 10) * Math.exp(-l * l / 0.0007); }
    const cl = f > 500 ? 1 : (f / 500) * (f / 500);
    for (let c = 0; c < NX; c++) {
      const i = c * NY + r;
      P[i] += floor * hissTilt * tex[i] + hum * (0.92 + 0.16 * tex[(i * 7) % N] / 4);
    }
    if (clickCols.length) for (const cc of clickCols) {
      for (let dc = -1; dc <= 1; dc++) {
        const c = cc + dc;
        if (c < 0 || c >= NX) continue;
        P[c * NY + r] += Math.pow(10, -3.1) * cl * (dc ? 0.25 : 1) * (0.5 + 0.5 * tex[c * NY + r]);
      }
    }
  }
  const img = new ImageData(NX, NY), px = img.data;
  for (let c = 0; c < NX; c++) {
    for (let r = 0; r < NY; r++) {
      const db = 10 * Math.log10(P[c * NY + r] + 1e-12);
      let v = (db + 96) / 84;
      v = v < 0 ? 0 : v > 1 ? 1 : Math.pow(v, 1.3);
      const li = Math.round(v * 255) * 3, o = (r * NX + c) * 4;
      px[o] = LUT[li]; px[o + 1] = LUT[li + 1]; px[o + 2] = LUT[li + 2]; px[o + 3] = 255;
    }
  }
  return img;
}

function toCanvas(img) {
  const off = document.createElement("canvas");
  off.width = img.width; off.height = img.height;
  off.getContext("2d").putImageData(img, 0, 0);
  return off;
}
function blit(cv, off) {
  const w = plot.clientWidth, h = plot.clientHeight;
  if (!w || !h || !off) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const W = Math.round(w * dpr), H = Math.round(h * dpr);
  if (cv.width !== W || cv.height !== H) { cv.width = W; cv.height = H; }
  const x = cv.getContext("2d");
  x.imageSmoothingEnabled = true;
  x.imageSmoothingQuality = "high";
  x.drawImage(off, 0, 0, W, H);
}
const fixes = () => { const o = {}; boxes.forEach((b) => { o[b.value] = b.checked; }); return o; };
function paintAfter() { offB = toCanvas(render(fixes())); blit(cvB, offB); }

let lastKey = "";
function build() {
  const w = plot.clientWidth, h = plot.clientHeight;
  if (!w || !h) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const nx = Math.max(300, Math.min(900, Math.round(w * dpr * 0.55)));
  const ny = Math.max(120, Math.min(320, Math.round(h * dpr * 0.6)));
  const key = nx + "x" + ny;
  if (key !== lastKey) {
    lastKey = key;
    prepare(nx, ny);
    offA = toCanvas(render({}));
    offB = toCanvas(render(fixes()));
  }
  blit(cvA, offA);
  blit(cvB, offB);
}

// ---------- axis + artefact notes ----------
[[8000, "8k"], [2000, "2k"], [500, "500"], [125, "125"], [50, "50"]].forEach(([f, l]) => {
  const li = document.createElement("li");
  li.style.setProperty("--y", yOf(f).toFixed(4));
  li.textContent = l;
  yAxis.appendChild(li);
});
const place = (k, x, y, flip) => {
  const li = notes[k];
  li.style.setProperty("--x", x.toFixed(4));
  li.style.setProperty("--y", y.toFixed(4));
  if (flip) li.dataset.flip = ""; else delete li.dataset.flip;
};
const firstEnd = phrases[0][1];
const clickT = clicks.slice().sort((p, q) => Math.abs(p - 3.6) - Math.abs(q - 3.6))[0];
place("hum", 0.025, yOf(50) - 0.01);
place("hiss", 0.03, 0.2);
place("verb", (firstEnd + 0.12) / T, yOf(700));
place("click", clickT / T, 0.2);

// ---------- the split ----------
let p = 0.5;
function setP(v, instant) {
  p = Math.max(0, Math.min(1, v));
  plot.classList.toggle("is-drag", !!instant);
  plot.style.setProperty("--bkw-compare-p", p.toFixed(4));
  const pct = Math.round(p * 100);
  split.setAttribute("aria-valuenow", String(pct));
  split.setAttribute("aria-valuetext", "Original on the left " + pct + "%, repaired on the right");
}
let drag = false;
const fromEvent = (e) => { const r = plot.getBoundingClientRect(); return (e.clientX - r.left) / r.width; };
plot.addEventListener("pointerdown", (e) => {
  if (e.button !== 0) return;
  drag = true;
  plot.setPointerCapture(e.pointerId);
  split.focus({ preventScroll: true });
  setP(fromEvent(e), e.target.closest(".bkw-compare__split") !== null);
});
plot.addEventListener("pointermove", (e) => { if (drag) setP(fromEvent(e), true); });
const stop = () => { drag = false; plot.classList.remove("is-drag"); };
plot.addEventListener("pointerup", stop);
plot.addEventListener("pointercancel", stop);
split.addEventListener("keydown", (e) => {
  const big = e.shiftKey ? 0.2 : 0.05;
  let v = p;
  if (e.key === "ArrowLeft" || e.key === "ArrowDown") v -= big;
  else if (e.key === "ArrowRight" || e.key === "ArrowUp") v += big;
  else if (e.key === "Home") v = 0;
  else if (e.key === "End") v = 1;
  else if (e.key === "PageDown") v -= 0.25;
  else if (e.key === "PageUp") v += 0.25;
  else return;
  e.preventDefault();
  setP(v, false);
});

// ---------- repairs ----------
const stats = Array.from(root.querySelectorAll(".bkw-compare__stat"));
boxes.forEach((b) => b.addEventListener("change", () => {
  paintAfter();
  const st = stats.find((s) => s.dataset.fix === b.value);
  const out = st.querySelector("b");
  out.textContent = b.checked ? out.dataset.after : out.dataset.before;
  if (b.checked) st.removeAttribute("data-off"); else st.setAttribute("data-off", "");
  out.classList.remove("is-flip");
  void out.offsetWidth;
  out.classList.add("is-flip");
}));

// ---------- mount ----------
buildLUT();
let rz = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  clearTimeout(rz);
  rz = setTimeout(() => { if (root.isConnected) build(); }, lastKey ? 120 : 0);
});
ro.observe(plot);
setP(0.5, true);

// first time it scrolls into view, the split sweeps once to show there are two sides
const io = new IntersectionObserver((ents) => {
  if (!root.isConnected) { io.disconnect(); return; }
  if (!ents.some((x) => x.isIntersecting)) return;
  io.disconnect();
  if (reduce) return;
  setTimeout(() => { if (root.isConnected && !drag) setP(0.78, false); }, 350);
  setTimeout(() => { if (root.isConnected && !drag) setP(0.5, false); }, 1150);
}, { threshold: 0.5 });
io.observe(plot);

css:
/* Halden — a scroll-scrubbed exploded view. Re-theme: --bkw-explode-bg, -ink, -accent, -metal. */
@property --bkw-explode-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.bkw-explode {
  --bkw-explode-bg: oklch(0.2 0.006 70);
  --bkw-explode-ink: oklch(0.94 0.01 80);
  --bkw-explode-accent: oklch(0.71 0.19 45);
  --bkw-explode-metal: oklch(0.78 0.01 250);
  --bkw-explode-line: color-mix(in oklch, var(--bkw-explode-ink) 13%, transparent);
  --bkw-explode-mute: color-mix(in oklch, var(--bkw-explode-ink) 56%, var(--bkw-explode-bg));
  --bkw-explode-panel: color-mix(in oklch, var(--bkw-explode-bg), black 22%);
  --bkw-explode-spring: linear(0, 0.026, 0.087, 0.169, 0.262, 0.357, 0.45, 0.537, 0.617, 0.687, 0.748, 0.801, 0.845, 0.882, 0.912, 0.936, 0.955, 0.97, 0.981, 0.989, 0.996, 1, 1.003, 1.005, 1.006, 1.006, 1.006, 1.006, 1.005, 1.005, 1.004, 1.004, 1.003, 1.003, 1.002, 1.002, 1);
  --bkw-explode-out: cubic-bezier(.2, .9, .25, 1);

  container-type: inline-size;
  container-name: bkw-explode;
  position: relative; box-sizing: border-box; width: 100%;
  border-radius: 24px; overflow: hidden;
  background: var(--bkw-explode-bg); color: var(--bkw-explode-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkw-explode-accent); outline-offset: 3px; border-radius: 6px; }
}
.bkw-explode__in {
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "view";
  gap: 26px; padding: clamp(20px, 4.4cqi, 54px);
}

/* ---------- copy ---------- */
.bkw-explode__copy { grid-area: copy; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; }
.bkw-explode__brand {
  display: inline-flex; align-items: center; gap: 9px; font: 700 15px/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase;
  & svg { width: 24px; height: 24px; fill: none; stroke: var(--bkw-explode-accent); stroke-width: 1.8; stroke-linecap: round; }
}
.bkw-explode__eyebrow { margin: 28px 0 12px; font: 600 11.5px/1.3 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--bkw-explode-mute); }
.bkw-explode__title { margin: 0; max-width: 14ch; font-size: clamp(2rem, 1.15rem + 3.3cqi, 3.2rem); line-height: 1; letter-spacing: -.045em; font-weight: 760; text-wrap: balance; }
.bkw-explode__lede { margin: 18px 0 0; max-width: 42ch; font-size: clamp(14.5px, 13.8px + .25cqi, 16.5px); line-height: 1.6; color: var(--bkw-explode-mute); text-wrap: pretty; }

.bkw-explode__rail {
  list-style: none; margin: 26px 0 0; padding: 0; width: 100%; max-width: 380px; display: grid; gap: 2px;
  counter-reset: none;
  & button {
    width: 100%; display: flex; align-items: center; gap: 14px; padding: 10px 12px; border: 0; border-radius: 10px; cursor: pointer;
    background: transparent; color: var(--bkw-explode-mute); font: 600 14px/1.2 system-ui, sans-serif; text-align: start;
    transition: color .25s, background-color .25s;
  }
  & button span { font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; color: color-mix(in oklch, var(--bkw-explode-ink) 35%, transparent); transition: color .25s; }
  & button:hover { color: var(--bkw-explode-ink); background: color-mix(in oklch, var(--bkw-explode-ink) 5%, transparent); }
  & button[aria-current="step"] { color: var(--bkw-explode-ink); background: color-mix(in oklch, var(--bkw-explode-accent) 14%, transparent); }
  & button[aria-current="step"] span { color: var(--bkw-explode-accent); }
}
.bkw-explode__buy {
  margin-top: 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;
  & > p { margin: 0; font: 500 12px/1.4 ui-monospace, Menlo, monospace; color: var(--bkw-explode-mute); }
}
.bkw-explode__cta {
  padding: 13px 20px; border: 0; border-radius: 999px; cursor: pointer; font-family: inherit; font-weight: 650; font-size: 14.5px; background: var(--bkw-explode-accent); color: oklch(0.18 0.02 45);
  transition: translate .35s var(--bkw-explode-spring), background-color .25s, color .25s, box-shadow .25s;
  &:hover { translate: 0 -2px; background: color-mix(in oklch, var(--bkw-explode-accent), white 12%); }
  &.is-done { background: color-mix(in oklch, var(--bkw-explode-accent) 14%, transparent); color: var(--bkw-explode-ink); box-shadow: inset 0 0 0 1.5px var(--bkw-explode-accent); }
}
/* the pre-order sheet opens in place under the button */
.bkw-explode__order {
  flex: 1 1 100%; max-width: 400px; padding: 14px 16px; border-radius: 16px;
  background: var(--bkw-explode-panel); box-shadow: inset 0 0 0 1px var(--bkw-explode-line);
  animation: bkw-explode-sheet .4s var(--bkw-explode-out);
  & p { margin: 0; display: grid; gap: 4px; font-size: 13.5px; line-height: 1.45; }
  & p > b { font-weight: 650; }
  & p > span { color: var(--bkw-explode-mute); }
  & [hidden] { display: none; }
}
.bkw-explode__ref { font-family: ui-monospace, Menlo, monospace; color: var(--bkw-explode-ink); }
.bkw-explode__acts {
  display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px;
  & button {
    padding: 9px 14px; border: 0; border-radius: 999px; cursor: pointer; font: 600 13px/1 system-ui, sans-serif;
    background: color-mix(in oklch, var(--bkw-explode-ink) 8%, transparent); color: var(--bkw-explode-ink); transition: background-color .2s;
  }
  & button:hover { background: color-mix(in oklch, var(--bkw-explode-ink) 15%, transparent); }
  & .bkw-explode__ok { background: var(--bkw-explode-accent); color: oklch(0.18 0.02 45); }
  & .bkw-explode__ok:hover { background: color-mix(in oklch, var(--bkw-explode-accent), white 12%); }
}
@keyframes bkw-explode-sheet { from { opacity: 0; translate: 0 -6px; } }

/* ---------- the scroller ---------- */
.bkw-explode__view {
  grid-area: view; position: relative; min-width: 0; height: 470px; border-radius: 20px; overflow-y: auto; overflow-x: hidden;
  overscroll-behavior: contain; scrollbar-width: none;
  background:
    radial-gradient(55% 45% at var(--cx, 38%) 52%, color-mix(in oklch, var(--bkw-explode-accent) 9%, transparent), transparent 70%),
    radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--bkw-explode-ink) 12%, transparent) 1px, transparent 1.5px) 0 0 / 22px 22px,
    var(--bkw-explode-panel);
  box-shadow: inset 0 0 0 1px var(--bkw-explode-line);
  scroll-timeline: --bkw-explode-t block;
  &::-webkit-scrollbar { display: none; }
}
.bkw-explode__track { height: 230%; }
.bkw-explode__stage {
  --R: 70; --gap: 50; --P: 900; --cx: 30%;
  --u: min(1, var(--bkw-explode-p) / .16);
  --tilt: calc(64 * var(--u) * var(--u) * (3 - 2 * var(--u)));
  position: sticky; top: 0; height: 100%;
  perspective: calc(var(--P) * 1px);
  perspective-origin: var(--cx) 50%;
  overflow: hidden;
}
@supports (animation-timeline: scroll()) {
  .bkw-explode__stage { animation: bkw-explode-p linear both; animation-timeline: --bkw-explode-t; }
}
@keyframes bkw-explode-p { from { --bkw-explode-p: 0; } to { --bkw-explode-p: 1; } }

.bkw-explode__phase {
  position: absolute; z-index: 3; top: 16px; left: 18px; right: 18px; margin: 0; display: flex; justify-content: space-between; align-items: baseline;
  font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .12em; text-transform: uppercase; color: var(--bkw-explode-mute);
  & b { font-size: 13px; color: var(--bkw-explode-accent); letter-spacing: 0; font-variant-numeric: tabular-nums; }
}
.bkw-explode__hint {
  position: absolute; z-index: 3; left: 0; right: 0; bottom: 18px; margin: 0; display: flex; justify-content: center; align-items: center; gap: 8px;
  font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .1em; text-transform: uppercase; color: var(--bkw-explode-mute);
  opacity: clamp(0, 1 - var(--bkw-explode-p) * 14, 1);
  & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
  & path { animation: bkw-explode-wheel 1.6s cubic-bezier(.5, 0, .2, 1) infinite; }
}
@keyframes bkw-explode-wheel { 0% { translate: 0 0; opacity: 1; } 70% { translate: 0 4px; opacity: 0; } 100% { translate: 0 0; opacity: 0; } }
.bkw-explode__meter {
  position: absolute; z-index: 3; top: 48px; bottom: 48px; right: 14px; width: 2px; border-radius: 2px; background: var(--bkw-explode-line);
  &::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--bkw-explode-accent); transform-origin: top; scale: 1 var(--bkw-explode-p); }
}
.bkw-explode__shadow {
  position: absolute; left: var(--cx); top: 50%; width: calc(var(--R) * 2.6px); height: calc(var(--R) * 1px);
  translate: -50% calc(var(--R) * .9px + var(--bkw-explode-p) * var(--gap) * 1.6px);
  border-radius: 50%;
  background: radial-gradient(closest-side, color-mix(in oklch, black 70%, transparent), transparent);
  opacity: calc(var(--u) * (1 - var(--bkw-explode-p) * .5));
  filter: blur(calc(6px + var(--bkw-explode-p) * 10px));
}

/* ---------- the object: shared per-layer arithmetic ---------- */
.bkw-explode__obj {
  position: absolute; inset: 0; transform-style: preserve-3d; transform-origin: var(--cx) 50%;
  transform: rotateX(calc(var(--tilt) * 1deg));
}
.bkw-explode__layer, .bkw-explode__call {
  --e: clamp(0, (var(--bkw-explode-p) - .1 - var(--i) * .05) / .34, 1);
  --s: calc(var(--e) * var(--e) * (3 - 2 * var(--e)));
  --f: calc((var(--bkw-explode-p) - .52) * 10.4);
  --h: max(0, 1 - max(var(--f) - var(--i) - .5, var(--i) + .5 - var(--f)) * .9);
  --on: clamp(0, (var(--bkw-explode-p) - .5) * 30, 1);
  --z: calc(var(--base) * var(--R) / 110 + (2 - var(--i)) * var(--gap) * var(--s) + var(--h) * 14);
  --dim: calc(1 - var(--on) * (1 - max(var(--h), .42)));
}
.bkw-explode__layer {
  --d: calc(var(--R) * 2);
  position: absolute; left: var(--cx); top: 50%; width: calc(var(--d) * 1px); height: calc(var(--d) * 1px);
  margin: calc(var(--d) * -.5px) 0 0 calc(var(--d) * -.5px);
  transform-style: preserve-3d;
  transform: translateZ(calc(var(--z) * 1px)) rotateZ(calc(var(--bkw-explode-p) * 90deg * var(--spin, 0)));
  & > i, & > .bkw-explode__face { position: absolute; inset: 0; border-radius: 50%; opacity: var(--dim); }
  & > i { background: color-mix(in oklch, var(--edge, var(--bkw-explode-metal)), black 35%); }
  & > i:nth-child(1) { transform: translateZ(calc(var(--t) * -1px)); }
  & > i:nth-child(2) { transform: translateZ(calc(var(--t) * -.66px)); }
  & > i:nth-child(3) { transform: translateZ(calc(var(--t) * -.33px)); }
}
.bkw-explode__layer--glass {
  --d: calc(var(--R) * 1.96); --edge: color-mix(in oklch, white 50%, transparent);
  & > i { background: color-mix(in oklch, white 7%, transparent); }
  & .bkw-explode__face {
    background: radial-gradient(circle at 50% 50%, transparent 60%, color-mix(in oklch, white 10%, transparent) 72%, transparent 73%), color-mix(in oklch, white 4%, transparent);
    box-shadow: inset 0 0 0 1.5px color-mix(in oklch, white 40%, transparent), inset 0 0 18px color-mix(in oklch, white 12%, transparent);
  }
}
.bkw-explode__sheen { position: absolute; inset: 0; border-radius: 50%; background: linear-gradient(125deg, color-mix(in oklch, white 34%, transparent) 8%, transparent 32%, transparent 64%, color-mix(in oklch, white 10%, transparent) 78%, transparent 90%); }
.bkw-explode__layer--disp {
  --d: calc(var(--R) * 1.56); --edge: oklch(0.2 0 0);
  & .bkw-explode__face { background: radial-gradient(circle at 50% 40%, oklch(0.2 0.01 60), oklch(0.08 0 0) 70%); box-shadow: inset 0 0 0 2px oklch(0.27 0 0); }
}
.bkw-explode__ui {
  position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 2px; text-align: center; container-type: inline-size;
  & .bkw-explode__ticks { position: absolute; inset: 0; width: 100%; height: 100%; }
  & line { stroke: oklch(0.42 0 0); stroke-width: .9; stroke-linecap: round; }
  & line.on { stroke: var(--bkw-explode-accent); }
}
.bkw-explode__temp { font: 300 25cqi/1 system-ui, sans-serif; letter-spacing: -.05em; font-variant-numeric: tabular-nums; color: oklch(0.97 0.01 80); }
.bkw-explode__mode { font: 700 6.5cqi/1 ui-monospace, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase; color: var(--bkw-explode-accent); }
.bkw-explode__now { font: 500 6.5cqi/1 system-ui, sans-serif; color: oklch(0.65 0.01 80); }
.bkw-explode__layer--ring {
  --spin: 1; --edge: var(--bkw-explode-metal);
  & > i, & .bkw-explode__face { -webkit-mask: radial-gradient(closest-side, transparent 77%, black 77.5%); mask: radial-gradient(closest-side, transparent 77%, black 77.5%); }
  & .bkw-explode__face {
    background:
      radial-gradient(closest-side, transparent 76%, color-mix(in oklch, black 30%, transparent) 79%, transparent 83%, transparent 95%, color-mix(in oklch, black 35%, transparent) 100%),
      conic-gradient(from 210deg, color-mix(in oklch, var(--bkw-explode-metal), white 35%), color-mix(in oklch, var(--bkw-explode-metal), black 25%) 25%, color-mix(in oklch, var(--bkw-explode-metal), white 25%) 50%, color-mix(in oklch, var(--bkw-explode-metal), black 30%) 75%, color-mix(in oklch, var(--bkw-explode-metal), white 35%)),
      var(--bkw-explode-metal);
  }
  & .bkw-explode__face::before {
    content: ""; position: absolute; inset: 0; border-radius: 50%;
    background: repeating-conic-gradient(color-mix(in oklch, black 26%, transparent) 0 1deg, color-mix(in oklch, white 22%, transparent) 1deg 2deg);
    -webkit-mask: radial-gradient(closest-side, transparent 86%, black 87%, black 98%, transparent 99%); mask: radial-gradient(closest-side, transparent 86%, black 87%, black 98%, transparent 99%);
  }
}
.bkw-explode__notch { position: absolute; top: 2.5%; left: 50%; width: 3px; height: 8%; margin-left: -1.5px; border-radius: 2px; background: var(--bkw-explode-accent); }
.bkw-explode__layer--logic {
  --d: calc(var(--R) * 1.8); --edge: oklch(0.32 0.05 160);
  & .bkw-explode__face { background: radial-gradient(circle at 40% 35%, oklch(0.36 0.06 165), oklch(0.24 0.045 165)); box-shadow: inset 0 0 0 1.5px oklch(0.45 0.06 165); }
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; }
  & .tr path { fill: none; stroke: oklch(0.55 0.08 160); stroke-width: .9; stroke-linecap: round; stroke-linejoin: round; }
  & .pd circle { fill: oklch(0.8 0.12 85); }
  & .chip { fill: oklch(0.16 0 0); stroke: oklch(0.4 0 0); stroke-width: .4; }
  & .chip2 { fill: oklch(0.2 0 0); }
  & .rf { fill: oklch(0.78 0.02 250); }
  & .ant { fill: none; stroke: oklch(0.8 0.12 85); stroke-width: .8; }
  & .sens { fill: oklch(0.85 0.03 80); }
  & text { font: 700 5px ui-monospace, Menlo, monospace; fill: oklch(0.6 0 0); }
}
.bkw-explode__layer--base {
  --d: calc(var(--R) * 2.08); --edge: oklch(0.62 0.005 80);
  & > i, & .bkw-explode__face { border-radius: 24%; }
  & .bkw-explode__face { background: linear-gradient(145deg, oklch(0.74 0.005 80), oklch(0.58 0.006 80)); box-shadow: inset 0 0 0 1px oklch(0.8 0.005 80); }
}
.bkw-explode__screw {
  position: absolute; width: 7%; height: 7%; border-radius: 50%; background: radial-gradient(circle at 40% 35%, oklch(0.85 0 0), oklch(0.5 0 0)); box-shadow: inset 0 0 0 1px oklch(0.45 0 0);
  &::after { content: ""; position: absolute; left: 20%; right: 20%; top: 50%; height: 1.5px; margin-top: -.75px; background: oklch(0.38 0 0); rotate: 30deg; }
  &:nth-child(1) { left: 8%; top: 8%; } &:nth-child(2) { right: 8%; top: 8%; } &:nth-child(3) { left: 8%; bottom: 8%; } &:nth-child(4) { right: 8%; bottom: 8%; }
}
.bkw-explode__term { position: absolute; left: 30%; right: 30%; top: 40%; height: 14%; display: flex; gap: 4%; padding: 2%; border-radius: 4px; background: oklch(0.32 0.01 80);
  & i { flex: 1; border-radius: 2px; background: radial-gradient(circle, oklch(0.8 0.1 85) 30%, oklch(0.25 0 0) 34%); } }
.bkw-explode__emb { position: absolute; left: 0; right: 0; bottom: 24%; text-align: center; font: 700 calc(var(--R) * .085px)/1 ui-monospace, Menlo, monospace; letter-spacing: .2em; color: oklch(0.52 0.006 80); text-shadow: 0 1px 0 oklch(0.78 0 0); }

/* ---------- callouts, pinned to the projected layer centres ---------- */
.bkw-explode__calls { list-style: none; margin: 0; padding: 0; position: absolute; inset: 0; pointer-events: none; }
.bkw-explode__call {
  --sn: sin(calc(var(--tilt) * 1deg));
  --cs: cos(calc(var(--tilt) * 1deg));
  --k: calc(var(--P) / (var(--P) - var(--z) * var(--cs)));
  --col: calc(var(--R) * 1.12 + 26);
  position: absolute; left: calc(var(--cx) + var(--col) * 1px); right: 30px; top: 50%;
  translate: calc((1 - var(--e)) * 14px) calc(-1px * var(--z) * var(--sn) * var(--k) - 50%);
  opacity: calc(clamp(0, (var(--e) - .55) * 3, 1) * (1 - var(--on) * (1 - max(var(--h), .45))));
  display: grid; gap: 2px;
  &::before {
    content: ""; position: absolute; top: .62em; right: calc(100% + 6px);
    width: max(0px, calc((var(--col) - var(--R) * var(--k) * .98) * 1px - 10px)); height: 1px;
    background: linear-gradient(90deg, var(--bkw-explode-accent) 3px, color-mix(in oklch, var(--bkw-explode-ink) 30%, transparent) 3px);
  }
  & b { display: flex; align-items: baseline; gap: 8px; font-size: 13.5px; font-weight: 650; }
  & b span { font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--bkw-explode-accent); }
  & em { font: 500 11px/1.35 ui-monospace, Menlo, monospace; font-style: normal; color: var(--bkw-explode-mute); }
}
.bkw-explode__detail {
  position: absolute; z-index: 3; left: 18px; right: 34px; bottom: 16px; min-height: 3.2em;
  & p {
    margin: 0; max-width: 46ch; font-size: 13px; line-height: 1.5; color: color-mix(in oklch, var(--bkw-explode-ink) 82%, transparent); text-wrap: pretty;
    transition: opacity .45s var(--bkw-explode-out), translate .6s var(--bkw-explode-spring), filter .45s;
    @starting-style { opacity: 0; translate: 0 8px; filter: blur(4px); }
  }
  & p b { color: var(--bkw-explode-accent); font: 600 11px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; margin-right: 8px; }
  & p.is-out { position: absolute; left: 0; bottom: 0; opacity: 0; translate: 0 -6px; filter: blur(4px); }
}

/* ---------- section layout ---------- */
@container bkw-explode (min-width: 560px) {
  .bkw-explode__stage { --R: 92; --gap: 66; --cx: 32%; }
  .bkw-explode__view { height: 520px; }
}
@container bkw-explode (min-width: 900px) {
  .bkw-explode__in { grid-template-columns: minmax(280px, .78fr) minmax(0, 1.3fr); grid-template-areas: "copy view"; gap: clamp(32px, 4.5cqi, 60px); align-items: center; }
  .bkw-explode__stage { --R: 100; --gap: 78; --cx: 34%; }
  .bkw-explode__view { height: 600px; }
}
@container bkw-explode (max-width: 559.98px) {
  .bkw-explode__rail { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 4px; max-width: none;
    & button { flex-direction: column; align-items: flex-start; gap: 5px; padding: 8px; font-size: 11.5px; }
  }
  .bkw-explode__call { right: 14px; & b { font-size: 12.5px; } & em { display: none; } }
  .bkw-explode__detail p { font-size: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-explode .bkw-explode__stage { animation: none; --bkw-explode-p: .5; position: relative; }
  .bkw-explode .bkw-explode__track { display: none; }
  .bkw-explode .bkw-explode__view { overflow: hidden; }
  .bkw-explode .bkw-explode__hint { display: none; }
  .bkw-explode .bkw-explode__hint path, .bkw-explode .bkw-explode__cta, .bkw-explode .bkw-explode__order { animation: none; transition: none; }
}

js:
// Halden exploded view. CSS owns the motion (a scroll-timeline drives --bkw-explode-p); this
// script reads the same progress to update text — the set point, the phase label and the
// rail's aria-current — and only writes the property itself where scroll timelines are missing.
const view = root.querySelector(".bkw-explode__view");
const stage = root.querySelector(".bkw-explode__stage");
const temp = root.querySelector(".bkw-explode__temp");
const setOut = root.querySelector(".bkw-explode__set");
const phase = root.querySelector(".bkw-explode__phase span");
const btns = Array.from(root.querySelectorAll(".bkw-explode__rail button"));
const NAMES = btns.map((b) => b.lastChild.textContent.trim());
const detail = root.querySelector(".bkw-explode__detail");
function showDetail(i) {
  detail.querySelectorAll("p").forEach((old) => {
    if (old.classList.contains("is-out")) { old.remove(); return; }
    old.classList.add("is-out");
    setTimeout(() => old.remove(), 450);
  });
  if (i < 0) return;
  const p = document.createElement("p");
  const b = document.createElement("b");
  b.textContent = "0" + (i + 1);
  p.append(b, btns[i].dataset.d);
  detail.appendChild(p);
}
const native = typeof CSS !== "undefined" && CSS.supports && CSS.supports("animation-timeline: scroll()");
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

// focus phase: the second half of the scroll visits each layer for a tenth of the range
const FOCUS0 = 0.52, SPAN = 1 / 10.4;
const centreOf = (i) => FOCUS0 + (i + 0.5) * SPAN;

let lastP = -1, pending = 0, current = -1, manualP = null;
function progress() {
  if (manualP !== null) return manualP;
  const max = view.scrollHeight - view.clientHeight;
  return max > 0 ? Math.min(1, Math.max(0, view.scrollTop / max)) : 0;
}
function update() {
  pending = 0;
  if (!root.isConnected) return;
  const p = progress();
  if (Math.abs(p - lastP) < 0.0005) return;
  lastP = p;
  if (!native || manualP !== null) stage.style.setProperty("--bkw-explode-p", p.toFixed(4));
  // the ring turns 90deg over the whole scroll: 45 detents, a tenth of a degree each
  const sp = (180 + Math.round(p * 45)) / 10;
  const txt = sp.toFixed(1);
  if (temp.textContent !== txt) { temp.textContent = txt; setOut.textContent = txt + "°"; }
  const f = (p - FOCUS0) / SPAN;
  const idx = p < FOCUS0 ? -1 : Math.max(0, Math.min(4, Math.floor(f)));
  if (idx !== current) {
    current = idx;
    btns.forEach((b, j) => { if (j === idx) b.setAttribute("aria-current", "step"); else b.removeAttribute("aria-current"); });
    showDetail(idx);
  }
  const label = idx >= 0 ? "0" + (idx + 1) + " / 05 \u00b7 " + NAMES[idx] : p > 0.36 ? "Exploded" : p > 0.04 ? "Separating" : "Assembled";
  if (phase.textContent !== label) phase.textContent = label;
}
const schedule = () => {
  if (!root.isConnected) { view.removeEventListener("scroll", schedule); return; }
  if (!pending) pending = requestAnimationFrame(() => { if (!root.isConnected) return; update(); });
};
view.addEventListener("scroll", schedule, { passive: true });

// the rail: arrows move between layers, Enter/click scrolls that layer into focus
function go(i) {
  if (reduce) {
    manualP = centreOf(i);
    lastP = -1;
    update();
    return;
  }
  const max = view.scrollHeight - view.clientHeight;
  view.scrollTo({ top: centreOf(i) * max, behavior: "smooth" });
}
btns.forEach((b, i) => {
  b.addEventListener("click", () => go(i));
  b.addEventListener("keydown", (e) => {
    let j = -1;
    if (e.key === "ArrowDown" || e.key === "ArrowRight") j = (i + 1) % btns.length;
    else if (e.key === "ArrowUp" || e.key === "ArrowLeft") j = (i - 1 + btns.length) % btns.length;
    else if (e.key === "Home") j = 0;
    else if (e.key === "End") j = btns.length - 1;
    if (j < 0) return;
    e.preventDefault();
    btns.forEach((x, k) => { x.tabIndex = k === j ? 0 : -1; });
    btns[j].focus();
  });
});

// pre-order: the button opens a confirmation sheet in place; confirming reserves, and the
// same sheet then offers the cancellation
const cta = root.querySelector(".bkw-explode__cta");
const order = root.querySelector(".bkw-explode__order");
const ask = root.querySelector(".bkw-explode__ask");
const done = root.querySelector(".bkw-explode__done");
const ship = root.querySelector(".bkw-explode__ship");
const ref = root.querySelector(".bkw-explode__ref");
const CTA = cta.textContent, SHIP = ship.textContent;
let reserved = false, shipTimer = 0;
order.id = "bkw-explode-order-" + Math.random().toString(36).slice(2, 8);
cta.setAttribute("aria-controls", order.id);
function sheet(open) {
  order.hidden = !open;
  cta.setAttribute("aria-expanded", String(open));
  ask.hidden = reserved;
  done.hidden = !reserved;
}
function reserve(on) {
  reserved = on;
  clearTimeout(shipTimer);
  cta.classList.toggle("is-done", on);
  cta.textContent = on ? "Pre-ordered \u2713" : CTA;
  if (on) {
    ref.textContent = "HD2-" + String(1000 + Math.floor(Math.random() * 9000));
    ship.textContent = "Reserved \u00b7 ships 18\u00a0November";
  } else {
    ship.textContent = "Pre-order cancelled. Nothing was charged.";
    shipTimer = setTimeout(() => { if (root.isConnected && !reserved) ship.textContent = SHIP; }, 2600);
  }
}
cta.addEventListener("click", () => sheet(order.hidden));
root.querySelector(".bkw-explode__ok").addEventListener("click", () => { reserve(true); sheet(true); cta.focus(); });
root.querySelector(".bkw-explode__no").addEventListener("click", () => { sheet(false); cta.focus(); });
root.querySelector(".bkw-explode__cancel").addEventListener("click", () => { reserve(false); sheet(false); cta.focus(); });
// Escape closes the sheet from anywhere in the buy area, the button included
root.querySelector(".bkw-explode__buy").addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !order.hidden) { e.preventDefault(); sheet(false); cta.focus(); }
});

if (reduce) manualP = 0.5;
update();

css:
/* Mise — a hotspot tour over a drawn interface. Re-theme: --bkw-tour-paper, -ink, -accent, -green. */
.bkw-tour {
  --bkw-tour-paper: oklch(0.968 0.016 82);
  --bkw-tour-ink: oklch(0.25 0.025 50);
  --bkw-tour-accent: oklch(0.6 0.19 32);
  --bkw-tour-green: oklch(0.55 0.1 150);
  --bkw-tour-card: color-mix(in oklch, var(--bkw-tour-paper), white 70%);
  --bkw-tour-line: color-mix(in oklch, var(--bkw-tour-ink) 12%, transparent);
  --bkw-tour-mute: color-mix(in oklch, var(--bkw-tour-ink) 60%, var(--bkw-tour-paper));
  --bkw-tour-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --bkw-tour-spring: linear(0, 0.027, 0.093, 0.182, 0.282, 0.386, 0.486, 0.579, 0.663, 0.737, 0.8, 0.852, 0.895, 0.929, 0.956, 0.976, 0.991, 1.002, 1.009, 1.013, 1.016, 1.017, 1.016, 1.015, 1.014, 1.012, 1.011, 1.009, 1.007, 1.006, 1.005, 1.004, 1.003, 1.002, 1.001, 1.001, 1);
  --bkw-tour-out: cubic-bezier(.2, .8, .2, 1);

  container-type: inline-size;
  container-name: bkw-tour;
  position: relative; box-sizing: border-box; width: 100%;
  border-radius: 24px; overflow: hidden;
  background: var(--bkw-tour-paper); color: var(--bkw-tour-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--bkw-tour-accent); outline-offset: 3px; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.bkw-tour__in { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "stage"; gap: 28px; padding: clamp(20px, 4.4cqi, 54px); }

/* ---------- editorial header ---------- */
.bkw-tour__head { grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "eyebrow" "title" "lede"; gap: 14px; }
.bkw-tour__eyebrow {
  grid-area: eyebrow; margin: 0; display: flex; align-items: center; gap: 8px; padding-bottom: 14px; border-bottom: 1px solid var(--bkw-tour-ink);
  font-size: 12px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase;
  & svg { width: 20px; height: 20px; color: var(--bkw-tour-accent); }
}
.bkw-tour__title {
  grid-area: title; margin: 0; max-width: 18ch;
  font: 500 clamp(2rem, 1.1rem + 3.6cqi, 3.5rem)/1.02 var(--bkw-tour-serif); letter-spacing: -.025em; text-wrap: balance;
  & em { font-style: italic; color: var(--bkw-tour-accent); }
}
.bkw-tour__lede { grid-area: lede; margin: 0; max-width: 48ch; font-size: clamp(14.5px, 13.8px + .25cqi, 16.5px); line-height: 1.6; color: var(--bkw-tour-mute); text-wrap: pretty; }

/* ---------- the drawn app ---------- */
.bkw-tour__stage { grid-area: stage; position: relative; min-width: 0; isolation: isolate; border-radius: 16px; }
.bkw-tour__app {
  --a-bg: oklch(0.992 0.004 85);
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "main" "aside";
  border-radius: 16px; overflow: hidden; background: var(--a-bg); border: 1px solid var(--bkw-tour-line);
  box-shadow: 0 30px 60px -36px color-mix(in oklch, var(--bkw-tour-ink) 45%, transparent);
  font-size: 13px;
}
.bkw-tour__top {
  grid-area: top; display: flex; align-items: center; gap: 14px; padding: 11px 14px; border-bottom: 1px solid var(--bkw-tour-line);
  & svg { width: 16px; height: 16px; }
}
.bkw-tour__logo { display: flex; align-items: center; gap: 6px; font: 600 17px/1 var(--bkw-tour-serif); & svg { width: 20px; height: 20px; color: var(--bkw-tour-accent); } }
.bkw-tour__crumb { color: var(--bkw-tour-mute); & i { font-style: normal; margin: 0 4px; opacity: .5; } }
.bkw-tour__search { display: none; margin-left: auto; align-items: center; gap: 7px; padding: 6px 10px; min-width: 190px; border-radius: 8px; background: color-mix(in oklch, var(--bkw-tour-ink) 5%, transparent); color: var(--bkw-tour-mute); }
.bkw-tour__me { margin-left: auto; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-size: 10.5px; font-weight: 700; color: white; background: var(--bkw-tour-green); }
.bkw-tour__side { display: none; grid-area: side; flex-direction: column; gap: 2px; padding: 12px 8px; border-right: 1px solid var(--bkw-tour-line); color: var(--bkw-tour-mute);
  & span { display: flex; align-items: center; gap: 9px; padding: 7px 10px; border-radius: 8px; }
  & span.is-on { color: var(--bkw-tour-ink); background: color-mix(in oklch, var(--bkw-tour-accent) 10%, transparent); font-weight: 600; }
  & svg { width: 16px; height: 16px; } }
.bkw-tour__main { grid-area: main; min-width: 0; padding: 14px; display: grid; gap: 12px; align-content: start; }
.bkw-tour__alert {
  position: relative; display: flex; align-items: flex-start; gap: 10px; padding: 10px 12px; border-radius: 10px;
  background: color-mix(in oklch, var(--bkw-tour-accent) 9%, var(--a-bg)); border: 1px solid color-mix(in oklch, var(--bkw-tour-accent) 30%, transparent);
  & svg { width: 18px; height: 18px; flex: none; color: var(--bkw-tour-accent); margin-top: 1px; }
  & p { margin: 0; line-height: 1.45; text-wrap: pretty; padding-right: 22px; }
}
.bkw-tour__tablewrap { min-width: 0; }
.bkw-tour__table {
  width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & caption { text-align: start; padding: 2px 0 8px; font-size: 11.5px; color: var(--bkw-tour-mute); }
  & th, & td { padding: 9px 8px; text-align: end; border-bottom: 1px solid var(--bkw-tour-line); white-space: nowrap; }
  & th:first-child { text-align: start; white-space: normal; font-weight: 550; }
  & thead th { position: relative; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--bkw-tour-mute); }
  & tbody tr:last-child > * { border-bottom: 0; }
  & tbody tr:hover { background: color-mix(in oklch, var(--bkw-tour-ink) 3%, transparent); }
}
.bkw-tour__chip { display: inline-block; margin-left: 6px; padding: 1px 6px; border-radius: 99px; font-size: 10px; font-weight: 650; color: var(--bkw-tour-accent); background: color-mix(in oklch, var(--bkw-tour-accent) 10%, transparent); vertical-align: 1px; }
.bkw-tour__c-cost { position: relative; & span { font-weight: 600; } }
.bkw-tour__table tbody .bkw-tour__c-margin {
  position: relative; min-width: 92px;
  & span { position: relative; z-index: 1; font-weight: 600; color: color-mix(in oklch, var(--bkw-tour-green), black 20%); }
  & i { position: absolute; left: 8px; right: 8px; bottom: 5px; height: 3px; border-radius: 3px; background: var(--bkw-tour-line); }
  & i::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: var(--bkw-tour-green); transform-origin: left; scale: calc(var(--m) / 100) 1; }
  & i::before { content: ""; position: absolute; top: -3px; bottom: -3px; left: 70%; width: 1.5px; background: var(--bkw-tour-ink); z-index: 1; }
  &.is-low span { color: var(--bkw-tour-accent); }
  &.is-low i::after { background: var(--bkw-tour-accent); }
}
.bkw-tour__c-price, .bkw-tour__c-sold { display: none; }

.bkw-tour__aside { grid-area: aside; display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; padding: 0 14px 14px; align-content: start; }
.bkw-tour__card {
  position: relative; padding: 12px 14px; border-radius: 12px; border: 1px solid var(--bkw-tour-line); background: var(--a-bg);
  & h4 { margin: 0 0 6px; font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--bkw-tour-mute); }
}
.bkw-tour__card--chart svg { display: block; width: 100%; height: auto; stroke-width: 1; }
.bkw-tour__q { fill: color-mix(in oklch, var(--bkw-tour-green) 9%, transparent); stroke: none; }
.bkw-tour__ql { font: 600 8px system-ui, sans-serif; letter-spacing: .06em; text-transform: uppercase; fill: var(--bkw-tour-mute); stroke: none; }
.bkw-tour__ax { stroke: color-mix(in oklch, var(--bkw-tour-ink) 35%, transparent); }
.bkw-tour__avg { stroke: color-mix(in oklch, var(--bkw-tour-ink) 30%, transparent); stroke-dasharray: 3 3; }
.bkw-tour__axl { font: 500 8px system-ui, sans-serif; fill: var(--bkw-tour-mute); stroke: none; }
.bkw-tour__pt {
  & circle { fill: var(--bkw-tour-ink); stroke: var(--a-bg); stroke-width: 2; }
  & text { font: 600 9px system-ui, sans-serif; fill: var(--bkw-tour-ink); stroke: none; }
}
.bkw-tour__pt.is-star circle { fill: var(--bkw-tour-green); }
.bkw-tour__pt.is-plow circle { fill: var(--bkw-tour-accent); }
.bkw-tour__pt.is-dog circle { fill: var(--a-bg); stroke: var(--bkw-tour-ink); stroke-width: 1.5; }
.bkw-tour__card--order dl { margin: 0; display: grid; gap: 6px; font-variant-numeric: tabular-nums;
  & div { display: flex; justify-content: space-between; gap: 10px; } & dt { color: var(--bkw-tour-mute); } & dd { margin: 0; font-weight: 650; } }
.bkw-tour__send { display: block; margin-top: 10px; padding: 8px; border-radius: 8px; text-align: center; font-weight: 650; color: var(--a-bg); background: var(--bkw-tour-ink); }

/* ---------- beacons ---------- */
.bkw-tour__beacon {
  position: absolute; z-index: 2; top: -9px; right: -9px; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 50%; cursor: pointer;
  display: grid; place-items: center; background: var(--bkw-tour-accent); color: white; font: 700 11.5px/1 system-ui, sans-serif;
  box-shadow: 0 0 0 3px var(--a-bg, white), 0 4px 10px -2px color-mix(in oklch, var(--bkw-tour-accent) 60%, transparent);
  transition: scale .45s var(--bkw-tour-spring), background-color .2s;
  &::before { content: ""; position: absolute; inset: -3px; border-radius: 50%; border: 2px solid var(--bkw-tour-accent); animation: bkw-tour-ping 2.2s cubic-bezier(.2, .6, .3, 1) infinite; animation-delay: calc(var(--d, 0) * 1ms); }
  &:hover { scale: 1.15; }
  &[aria-current="step"] { background: var(--bkw-tour-ink); }
  &[aria-current="step"]::before { animation: none; opacity: 0; }
}
.bkw-tour thead .bkw-tour__beacon { top: -6px; right: -4px; }
@keyframes bkw-tour-ping { 0% { scale: 1; opacity: .9; } 70%, 100% { scale: 2.1; opacity: 0; } }

/* ---------- spotlight + card ---------- */
.bkw-tour__hole {
  position: absolute; z-index: 3; left: 0; top: 0; width: var(--w, 0px); height: var(--h, 0px); border-radius: 12px; pointer-events: none;
  translate: var(--x, 0px) var(--y, 0px);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkw-tour-accent) 70%, transparent), 0 0 0 3000px color-mix(in oklch, var(--bkw-tour-ink) 34%, transparent);
  opacity: 0;
  transition: translate .7s var(--bkw-tour-spring), width .7s var(--bkw-tour-spring), height .7s var(--bkw-tour-spring), opacity .35s var(--bkw-tour-out);
}
.bkw-tour__stage { overflow: clip; }
.bkw-tour__stage.is-on .bkw-tour__hole { opacity: 1; }
.bkw-tour__stage.is-snap .bkw-tour__hole, .bkw-tour__stage.is-snap .bkw-tour__card-tip { transition: opacity .35s var(--bkw-tour-out); }

.bkw-tour__card-tip {
  position: absolute; z-index: 4; left: 0; top: 0; width: min(310px, calc(100% - 24px));
  padding: 16px 16px 12px; border-radius: 14px; background: var(--bkw-tour-card); color: var(--bkw-tour-ink);
  box-shadow: 0 1px 0 color-mix(in oklch, white 60%, transparent) inset, 0 24px 48px -20px color-mix(in oklch, var(--bkw-tour-ink) 60%, transparent), 0 0 0 1px var(--bkw-tour-line);
  translate: var(--cx, 0px) var(--cy, 0px);
  transition: translate .7s var(--bkw-tour-spring), opacity .3s var(--bkw-tour-out);
  @starting-style { opacity: 0; }
  &[hidden] { display: block; opacity: 0; visibility: hidden; pointer-events: none; transition: opacity .2s, visibility 0s .2s; }
}
.bkw-tour__count { margin: 0; font-size: 11px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--bkw-tour-accent); font-variant-numeric: tabular-nums; }
.bkw-tour__tt { margin: 6px 0 0; font: 500 21px/1.15 var(--bkw-tour-serif); letter-spacing: -.01em; text-wrap: balance; }
.bkw-tour__tb { margin: 8px 0 0; font-size: 13.5px; line-height: 1.55; color: color-mix(in oklch, var(--bkw-tour-ink) 80%, transparent); text-wrap: pretty; }
.bkw-tour__tt, .bkw-tour__tb { animation: bkw-tour-in .5s var(--bkw-tour-out) both; }
.bkw-tour__tb { animation-delay: 60ms; }
@keyframes bkw-tour-in { from { opacity: 0; translate: 0 6px; } }
.bkw-tour__nav {
  display: flex; align-items: center; gap: 6px; margin-top: 14px; padding-top: 10px; border-top: 1px solid var(--bkw-tour-line);
  & button { display: inline-flex; align-items: center; gap: 4px; height: 32px; border: 0; border-radius: 8px; cursor: pointer; font: 600 13px/1 system-ui, sans-serif; color: inherit; background: transparent; }
  & button svg { width: 16px; height: 16px; stroke-width: 2; }
  & .bkw-tour__close, & .bkw-tour__prev { width: 32px; justify-content: center; }
  & .bkw-tour__close:hover, & .bkw-tour__prev:hover { background: color-mix(in oklch, var(--bkw-tour-ink) 7%, transparent); }
  & .bkw-tour__prev:disabled { opacity: .3; cursor: default; background: none; }
  & .bkw-tour__next { padding: 0 10px 0 14px; color: white; background: var(--bkw-tour-accent); transition: background-color .2s; }
  & .bkw-tour__next:hover { background: color-mix(in oklch, var(--bkw-tour-accent), black 12%); }
}
.bkw-tour__dots { display: flex; gap: 4px; margin: 0 auto;
  & i { width: 6px; height: 6px; border-radius: 99px; background: var(--bkw-tour-line); transition: width .45s var(--bkw-tour-spring), background-color .3s; }
  & i.is-on { width: 16px; background: var(--bkw-tour-accent); } }
.bkw-tour__restart {
  position: absolute; z-index: 4; right: 14px; bottom: 14px; padding: 9px 14px; border: 0; border-radius: 99px; cursor: pointer;
  font: 600 13px/1 system-ui, sans-serif; color: white; background: var(--bkw-tour-ink);
  box-shadow: 0 10px 20px -10px color-mix(in oklch, var(--bkw-tour-ink) 70%, transparent);
  transition: opacity .3s, translate .5s var(--bkw-tour-spring);
  @starting-style { opacity: 0; translate: 0 8px; }
  &[hidden] { display: none; }
}

/* ---------- responsive ---------- */
@container bkw-tour (min-width: 620px) {
  .bkw-tour__c-price, .bkw-tour__c-sold { display: table-cell; }
  .bkw-tour__aside { grid-template-columns: 1.25fr 1fr; }
}
@container bkw-tour (min-width: 860px) {
  .bkw-tour__head { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); grid-template-areas: "eyebrow eyebrow" "title lede"; column-gap: 48px; align-items: end; }
  .bkw-tour__app { grid-template-columns: 150px minmax(0, 1fr) 280px; grid-template-areas: "top top top" "side main aside"; }
  .bkw-tour__side { display: flex; }
  .bkw-tour__search { display: flex; }
  .bkw-tour__me { margin-left: 0; }
  .bkw-tour__aside { grid-template-columns: minmax(0, 1fr); padding: 14px 14px 14px 0; }
}
@container bkw-tour (max-width: 479.98px) {
  .bkw-tour__crumb { display: none; }
  .bkw-tour__main { padding: 12px 10px; }
  .bkw-tour__aside { padding: 0 10px 12px; }
  .bkw-tour__table { table-layout: fixed; font-size: 12.5px; }
  .bkw-tour__table th, .bkw-tour__table td { padding: 8px 5px; }
  .bkw-tour__table thead .bkw-tour__c-cost { width: 68px; }
  .bkw-tour__table thead .bkw-tour__c-margin { width: 72px; }
  .bkw-tour__table tbody .bkw-tour__c-margin { min-width: 0; }
  .bkw-tour__table thead .bkw-tour__beacon { right: 2px; }
  .bkw-tour__table thead th { white-space: normal; font-size: 9.5px; letter-spacing: .05em; line-height: 1.2; vertical-align: bottom; }
  .bkw-tour__chip { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-tour .bkw-tour__hole, .bkw-tour .bkw-tour__card-tip, .bkw-tour .bkw-tour__beacon, .bkw-tour .bkw-tour__dots i, .bkw-tour .bkw-tour__restart { transition: opacity .2s linear; }
  .bkw-tour .bkw-tour__beacon::before, .bkw-tour .bkw-tour__tt, .bkw-tour .bkw-tour__tb { animation: none; }
}

js:
// Mise tour. Targets are measured against the stage on every step and resize; the spotlight
// is one element sprung between them, and the step card tries right, left, below, then above.
const stage = root.querySelector(".bkw-tour__stage");
const hole = root.querySelector(".bkw-tour__hole");
const tip = root.querySelector(".bkw-tour__card-tip");
const tt = tip.querySelector(".bkw-tour__tt");
const tb = tip.querySelector(".bkw-tour__tb");
const nOut = tip.querySelector(".bkw-tour__n");
const prev = tip.querySelector(".bkw-tour__prev");
const next = tip.querySelector(".bkw-tour__next");
const close = tip.querySelector(".bkw-tour__close");
const dots = Array.from(tip.querySelectorAll(".bkw-tour__dots i"));
const restart = root.querySelector(".bkw-tour__restart");
const beacons = Array.from(root.querySelectorAll(".bkw-tour__beacon"));
const STEPS = Array.from(root.querySelectorAll(".bkw-tour__steps template")).map((t) => ({ title: t.dataset.title, body: t.innerHTML }));
const targets = STEPS.map((_, i) => root.querySelector('[data-step="' + (i + 1) + '"]'));
beacons.forEach((b, i) => b.style.setProperty("--d", String(i * 380)));

const uid = Math.random().toString(36).slice(2, 7);
tt.id = "bkw-tour-tip-title-" + uid;
tip.setAttribute("aria-labelledby", tt.id);

let cur = -1;
const PAD = 6, GAP = 14;

function rectOf(el) {
  const s = stage.getBoundingClientRect(), r = el.getBoundingClientRect();
  return { x: r.left - s.left, y: r.top - s.top, w: r.width, h: r.height, W: s.width, H: s.height };
}
function layout(snap) {
  if (cur < 0) return;
  const t = targets[cur];
  // the margin column is a header cell: grow the spotlight down over the whole column
  let r = rectOf(t);
  if (t.tagName === "TH") {
    const last = root.querySelector(".bkw-tour__table tbody tr:last-child .bkw-tour__c-margin");
    const lr = rectOf(last);
    r = { ...r, h: lr.y + lr.h - r.y };
  }
  const x = Math.max(2, r.x - PAD), y = Math.max(2, r.y - PAD);
  const w = Math.min(r.W - x - 2, r.w + PAD * 2), h = Math.min(r.H - y - 2, r.h + PAD * 2);
  stage.classList.toggle("is-snap", !!snap);
  hole.style.setProperty("--x", x + "px");
  hole.style.setProperty("--y", y + "px");
  hole.style.setProperty("--w", w + "px");
  hole.style.setProperty("--h", h + "px");

  const cw = tip.offsetWidth, ch = tip.offsetHeight;
  const fitsX = (cx) => cx >= 8 && cx + cw <= r.W - 8;
  const fitsY = (cy) => cy >= 8 && cy + ch <= r.H - 8;
  const clampX = (v) => Math.max(8, Math.min(r.W - cw - 8, v));
  const clampY = (v) => Math.max(8, Math.min(r.H - ch - 8, v));
  const options = [
    [x + w + GAP, clampY(y + h / 2 - ch / 2)],
    [x - GAP - cw, clampY(y + h / 2 - ch / 2)],
    [clampX(x + w / 2 - cw / 2), y + h + GAP],
    [clampX(x + w / 2 - cw / 2), y - GAP - ch]
  ];
  let pick = options.find(([cx, cy]) => fitsX(cx) && fitsY(cy));
  if (!pick) pick = [clampX(x + w / 2 - cw / 2), clampY(y + h + GAP)];
  tip.style.setProperty("--cx", Math.round(pick[0]) + "px");
  tip.style.setProperty("--cy", Math.round(pick[1]) + "px");
  if (snap) requestAnimationFrame(() => { if (!root.isConnected) return; stage.classList.remove("is-snap"); });
}
function go(i, focusTip) {
  const was = cur;
  cur = Math.max(0, Math.min(STEPS.length - 1, i));
  const s = STEPS[cur];
  nOut.textContent = String(cur + 1);
  tt.textContent = s.title;
  tb.innerHTML = s.body;
  [tt, tb].forEach((el) => { el.style.animation = "none"; void el.offsetWidth; el.style.animation = ""; });
  prev.disabled = cur === 0;
  next.firstChild.textContent = cur === STEPS.length - 1 ? "Done" : "Next";
  dots.forEach((d, j) => d.classList.toggle("is-on", j === cur));
  beacons.forEach((b) => { if (+b.dataset.go === cur) b.setAttribute("aria-current", "step"); else b.removeAttribute("aria-current"); });
  restart.hidden = true;
  tip.hidden = false;
  stage.classList.add("is-on");
  layout(was < 0);
  if (focusTip) next.focus({ preventScroll: true });
}
function end() {
  const last = cur;
  cur = -1;
  stage.classList.remove("is-on");
  tip.hidden = true;
  beacons.forEach((b) => b.removeAttribute("aria-current"));
  restart.hidden = false;
  if (last >= 0 && tip.contains(document.activeElement)) beacons[last].focus({ preventScroll: true });
}

beacons.forEach((b) => b.addEventListener("click", () => go(+b.dataset.go, true)));
next.addEventListener("click", () => { if (cur >= STEPS.length - 1) end(); else go(cur + 1); });
prev.addEventListener("click", () => go(cur - 1));
close.addEventListener("click", end);
restart.addEventListener("click", () => go(0, true));
stage.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && cur >= 0) { e.preventDefault(); end(); return; }
  if (cur < 0 || e.target.closest("input, textarea")) return;
  if (e.key === "ArrowRight") { e.preventDefault(); go(cur + 1); }
  else if (e.key === "ArrowLeft") { e.preventDefault(); go(cur - 1); }
  else if (e.key === "Home") { e.preventDefault(); go(0); }
  else if (e.key === "End") { e.preventDefault(); go(STEPS.length - 1); }
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  layout(true);
});
ro.observe(stage);
go(0);

css:
/* Quarry — a brutalist "since your version" changelog.
   Re-theme: --bkw-since-paper, -ink, -hi (highlighter), -red. */
@property --bkw-since-n { syntax: "<integer>"; inherits: true; initial-value: 0; }

.bkw-since {
  --bkw-since-paper: oklch(0.965 0.012 95);
  --bkw-since-ink: oklch(0.17 0.005 90);
  --bkw-since-hi: oklch(0.9 0.175 102);
  --bkw-since-red: oklch(0.6 0.22 28);
  --bkw-since-mute: color-mix(in oklch, var(--bkw-since-ink) 58%, var(--bkw-since-paper));
  --bkw-since-faint: color-mix(in oklch, var(--bkw-since-ink) 7%, var(--bkw-since-paper));
  --bkw-since-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkw-since-spring: linear(0, 0.036, 0.121, 0.238, 0.364, 0.494, 0.612, 0.72, 0.81, 0.885, 0.943, 0.986, 1.017, 1.036, 1.048, 1.052, 1.052, 1.048, 1.043, 1.037, 1.03, 1.023, 1.017, 1.012, 1.008, 1.004, 1.002, 1, 0.999, 0.998, 0.997, 0.997, 0.997, 0.998, 0.998, 0.998, 1);
  --bkw-since-snap: cubic-bezier(.5, 0, .1, 1);

  container-type: inline-size;
  container-name: bkw-since;
  position: relative; box-sizing: border-box; width: 100%;
  background: var(--bkw-since-paper); color: var(--bkw-since-ink);
  border: 2px solid var(--bkw-since-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; }
  & :focus-visible { outline: 3px solid var(--bkw-since-ink); outline-offset: 2px; }
  & code { font-family: var(--bkw-since-mono); font-size: .92em; padding: 0 .25em; background: var(--bkw-since-faint); border: 1px solid color-mix(in oklch, var(--bkw-since-ink) 18%, transparent); }
  & fieldset { margin: 0; padding: 0; border: 0; min-width: 0; }
}
.bkw-since__sr, .bkw-since__srl { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.bkw-since__in { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "side" "log"; }

/* ---------- left: question, picker, summary ---------- */
.bkw-since__side { grid-area: side; min-width: 0; padding: clamp(18px, 4cqi, 40px); display: grid; gap: 22px; align-content: start; }
.bkw-since__brand {
  margin: 0; display: flex; align-items: center; gap: 8px; font: 800 15px/1 var(--bkw-since-mono); letter-spacing: .08em;
  & svg { width: 22px; height: 22px; fill: var(--bkw-since-hi); stroke: var(--bkw-since-ink); stroke-width: 2; stroke-linejoin: round; }
  & span { font-weight: 500; color: var(--bkw-since-mute); letter-spacing: 0; }
}
.bkw-since__title {
  margin: 0; max-width: 13ch; font-size: clamp(2.1rem, 1.2rem + 4cqi, 3.6rem); line-height: .95; letter-spacing: -.045em; font-weight: 850; text-transform: uppercase; text-wrap: balance;
}
.bkw-since__pick legend { padding: 0; margin-bottom: 8px; font: 700 12px/1 var(--bkw-since-mono); letter-spacing: .1em; text-transform: uppercase; }
.bkw-since__vs {
  display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); border: 2px solid var(--bkw-since-ink); background: var(--bkw-since-paper);
  & label { position: relative; display: grid; place-items: center; height: 44px; cursor: pointer; font: 700 15px/1 var(--bkw-since-mono); font-variant-numeric: tabular-nums; }
  & label + label { border-left: 2px solid var(--bkw-since-ink); }
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & span { position: relative; z-index: 1; }
  & label::before { content: ""; position: absolute; inset: 0; background: var(--bkw-since-ink); clip-path: inset(100% 0 0 0); transition: clip-path .28s var(--bkw-since-snap); }
  & label:has(:checked)::before { clip-path: inset(0); }
  & label:has(:checked) { color: var(--bkw-since-hi); }
  & label:hover:not(:has(:checked)) { background: var(--bkw-since-hi); }
  & label:has(:focus-visible) { outline: 3px solid var(--bkw-since-red); outline-offset: -5px; }
}

.bkw-since__sum { display: grid; gap: 12px; }
.bkw-since__big {
  margin: 0; display: flex; align-items: flex-end; gap: 12px;
  & small { font: 700 13px/1.15 var(--bkw-since-mono); text-transform: uppercase; letter-spacing: .04em; padding-bottom: .55em; }
  & b { background: var(--bkw-since-hi); padding: 0 .2em; }
}
.bkw-since__n {
  counter-reset: bkw-since-n var(--bkw-since-n);
  transition: --bkw-since-n .6s cubic-bezier(.2, .7, .2, 1);
  font: 900 clamp(4.2rem, 2.8rem + 6cqi, 6.6rem)/.8 system-ui, sans-serif; letter-spacing: -.06em; font-variant-numeric: tabular-nums;
  &::after { content: counter(bkw-since-n); }
}
.bkw-since__bar {
  display: flex; height: 18px; border: 2px solid var(--bkw-since-ink); background: var(--bkw-since-faint);
  & i { flex: var(--c, 0) 1 0; min-width: 0; transition: flex-grow .55s var(--bkw-since-spring), opacity .3s; }
  & i + i { box-shadow: -2px 0 0 var(--bkw-since-ink); }
  & i[data-off] { opacity: .2; }
}
.bkw-since__bar [data-seg="feat"], .bkw-since__f--feat b { background: var(--bkw-since-hi); }
.bkw-since__bar [data-seg="fix"], .bkw-since__f--fix b { background: var(--bkw-since-ink); color: var(--bkw-since-paper); }
.bkw-since__bar [data-seg="perf"], .bkw-since__f--perf b { background: repeating-linear-gradient(-45deg, var(--bkw-since-ink) 0 2px, var(--bkw-since-paper) 2px 6px); }
.bkw-since__f--perf b { background: var(--bkw-since-paper); }
.bkw-since__bar [data-seg="break"], .bkw-since__f--break b { background: var(--bkw-since-red); color: white; }
.bkw-since__fs { display: flex; flex-wrap: wrap; gap: 8px; }
.bkw-since__f {
  position: relative; display: inline-flex; align-items: center; gap: 8px; padding: 0 0 0 10px; height: 34px; cursor: pointer;
  border: 2px solid var(--bkw-since-ink); background: var(--bkw-since-paper); font: 700 12px/1 var(--bkw-since-mono); text-transform: uppercase; letter-spacing: .04em;
  box-shadow: 3px 3px 0 var(--bkw-since-ink); transition: translate .15s var(--bkw-since-snap), box-shadow .15s var(--bkw-since-snap);
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & b { align-self: stretch; display: grid; place-items: center; min-width: 30px; padding: 0 6px; border-left: 2px solid var(--bkw-since-ink); font-variant-numeric: tabular-nums; }
  &:hover { translate: -1px -1px; box-shadow: 4px 4px 0 var(--bkw-since-ink); }
  &:not(:has(:checked)) { box-shadow: 0 0 0 var(--bkw-since-ink); translate: 3px 3px; color: var(--bkw-since-mute); background: var(--bkw-since-faint); }
  &:not(:has(:checked)) span { text-decoration: line-through 2px; }
  &:has(:focus-visible) { outline: 3px solid var(--bkw-since-red); outline-offset: 2px; }
}

.bkw-since__warn {
  border: 2px solid var(--bkw-since-ink); background: var(--bkw-since-paper); box-shadow: 6px 6px 0 var(--bkw-since-red);
  & h3 { margin: 0; display: flex; align-items: center; gap: 8px; padding: 9px 12px; font: 800 13px/1 var(--bkw-since-mono); text-transform: uppercase; letter-spacing: .06em; color: white; background: var(--bkw-since-red); }
  & h3 svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linejoin: round; stroke-linecap: round; }
  & ol { margin: 0; padding: 10px 12px 4px 32px; display: grid; gap: 6px; font-size: 14px; line-height: 1.4; }
  & li::marker { font: 700 12px var(--bkw-since-mono); }
  & li { animation: bkw-since-drop .4s var(--bkw-since-spring) both; animation-delay: calc(var(--i, 0) * 60ms); }
}
.bkw-since__warn.is-clear { box-shadow: 6px 6px 0 var(--bkw-since-hi);
  & h3 { background: var(--bkw-since-ink); color: var(--bkw-since-hi); }
  & ol { display: none; } }
@keyframes bkw-since-drop { from { opacity: 0; translate: 0 -6px; } }
.bkw-since__cmd {
  margin: 8px 12px 12px; display: flex; align-items: stretch; border: 2px solid var(--bkw-since-ink); background: var(--bkw-since-ink); color: var(--bkw-since-paper);
  & code { flex: 1; min-width: 0; padding: 9px 10px; background: none; border: 0; overflow-x: auto; white-space: nowrap; scrollbar-width: none; }
  & button { flex: none; border: 0; border-left: 2px solid var(--bkw-since-ink); padding: 0 12px; cursor: pointer; font: 700 12px/1 var(--bkw-since-mono); text-transform: uppercase; background: var(--bkw-since-hi); color: var(--bkw-since-ink); }
  & button:active { background: var(--bkw-since-paper); }
}

/* ---------- right: the log in its own scroller ---------- */
.bkw-since__log {
  grid-area: log; position: relative; min-width: 0; max-height: 560px; overflow-y: auto; overscroll-behavior: contain;
  border-top: 2px solid var(--bkw-since-ink); background: var(--bkw-since-paper);
  scrollbar-width: thin; scrollbar-color: var(--bkw-since-ink) var(--bkw-since-faint);
}
.bkw-since__rel {
  & h3 {
    position: sticky; top: 0; z-index: 2; margin: 0; display: flex; align-items: center; gap: 12px; padding: 10px clamp(14px, 3cqi, 24px);
    background: var(--bkw-since-paper); border-bottom: 2px solid var(--bkw-since-ink); font: 800 18px/1 var(--bkw-since-mono); letter-spacing: -.02em;
  }
  & time { font: 500 12px/1 var(--bkw-since-mono); color: var(--bkw-since-mute); letter-spacing: 0; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & + & { border-top: 0; }
}
.bkw-since__state { margin-left: auto; padding: 4px 7px; font: 800 10.5px/1 var(--bkw-since-mono); font-style: normal; letter-spacing: .08em; text-transform: uppercase; border: 2px solid var(--bkw-since-ink); }
.bkw-since__rel[data-state="new"] .bkw-since__state { background: var(--bkw-since-hi); }
.bkw-since__rel[data-state="have"] .bkw-since__state { color: var(--bkw-since-mute); border-color: color-mix(in oklch, var(--bkw-since-ink) 30%, transparent); }
.bkw-since__rel[data-state="current"] .bkw-since__state { background: var(--bkw-since-ink); color: var(--bkw-since-hi); }
.bkw-since__rel[data-state="have"] h3 > span, .bkw-since__rel[data-state="current"] h3 > span { color: var(--bkw-since-mute); }
.bkw-since__rel[data-state="have"] .bkw-since__item, .bkw-since__rel[data-state="current"] .bkw-since__item { opacity: .42; }

.bkw-since__item {
  display: grid; grid-template-columns: 92px minmax(0, 1fr) auto; gap: 14px; align-items: start;
  padding: 14px clamp(14px, 3cqi, 24px); border-bottom: 1px solid color-mix(in oklch, var(--bkw-since-ink) 22%, transparent);
  transition: opacity .3s, background-color .2s;
  & h4 { margin: 0; font-size: 15.5px; font-weight: 750; letter-spacing: -.01em; line-height: 1.25; text-wrap: balance; }
  & p { margin: 4px 0 0; font-size: 13.5px; line-height: 1.5; color: color-mix(in oklch, var(--bkw-since-ink) 76%, transparent); text-wrap: pretty; }
  &:hover { background: var(--bkw-since-faint); }
  &[hidden] { display: none; }
}
.bkw-since__tag {
  justify-self: start; padding: 4px 6px; border: 2px solid var(--bkw-since-ink); font: 800 10.5px/1 var(--bkw-since-mono); text-transform: uppercase; letter-spacing: .06em; white-space: nowrap;
}
.bkw-since__item[data-type="feat"] .bkw-since__tag { background: var(--bkw-since-hi); }
.bkw-since__item[data-type="fix"] .bkw-since__tag { background: var(--bkw-since-ink); color: var(--bkw-since-paper); }
.bkw-since__item[data-type="perf"] .bkw-since__tag { background: var(--bkw-since-paper); box-shadow: 2px 2px 0 var(--bkw-since-ink); }
.bkw-since__item[data-type="break"] .bkw-since__tag { background: var(--bkw-since-red); color: white; border-color: var(--bkw-since-red); }
.bkw-since__pr {
  display: inline-flex; align-items: center; gap: 6px; padding: 0; border: 0; background: none; cursor: pointer;
  font: 600 12px/1.6 var(--bkw-since-mono); color: var(--bkw-since-mute); text-decoration: none; white-space: nowrap;
  &::after { content: ""; width: 5px; height: 5px; margin-top: -3px; border: solid currentColor; border-width: 0 2px 2px 0; rotate: 45deg; transition: rotate .2s var(--bkw-since-snap), margin .2s var(--bkw-since-snap); }
  &:hover, &[aria-expanded="true"] { color: var(--bkw-since-ink); text-decoration: underline 2px; }
  &[aria-expanded="true"]::after { rotate: -135deg; margin-top: 3px; }
}
/* a pull request opened in place, under its entry */
.bkw-since__item > .bkw-since__more {
  grid-area: auto / 1 / auto / -1; margin: 2px 0 0; padding: 10px 12px;
  border: 2px solid var(--bkw-since-ink); background: var(--bkw-since-paper); box-shadow: 3px 3px 0 var(--bkw-since-ink);
  animation: bkw-since-drop .35s var(--bkw-since-spring) both;
  & p { margin: 0; font-size: 13.5px; line-height: 1.5; color: var(--bkw-since-ink); }
  & .bkw-since__meta { display: flex; flex-wrap: wrap; gap: 2px 14px; margin-bottom: 6px; font: 600 11.5px/1.5 var(--bkw-since-mono); color: var(--bkw-since-mute); }
  & ins { text-decoration: none; padding: 0 .25em; background: var(--bkw-since-hi); color: var(--bkw-since-ink); }
  & del { text-decoration: none; color: var(--bkw-since-red); }
  &[hidden] { display: none; }
}
.bkw-since__rel .bkw-since__item:has(> .bkw-since__more:not([hidden])) { opacity: 1; }
.bkw-since__empty { margin: 0; padding: 40px 24px; font: 700 14px/1.4 var(--bkw-since-mono); text-transform: uppercase; text-align: center; &[hidden] { display: none; } }

@container bkw-since (min-width: 900px) {
  .bkw-since__in { grid-template-columns: minmax(340px, .9fr) minmax(0, 1.1fr); grid-template-areas: "side log"; align-items: stretch; }
  /* size containment: the log never sizes the row, it fills whatever the left column needs and scrolls */
  .bkw-since__log { contain: size; max-height: none; border-top: 0; border-left: 2px solid var(--bkw-since-ink); }
}
@container bkw-since (max-width: 519.98px) {
  .bkw-since__item { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "tag pr" "body body"; gap: 8px 10px; }
  .bkw-since__tag { grid-area: tag; } .bkw-since__pr { grid-area: pr; } .bkw-since__item > div { grid-area: body; }
  .bkw-since__vs label { height: 40px; font-size: 13px; }
  .bkw-since__rel h3 { font-size: 16px; gap: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-since .bkw-since__n { transition: none; }
  .bkw-since .bkw-since__bar i, .bkw-since .bkw-since__vs label::before, .bkw-since .bkw-since__f, .bkw-since .bkw-since__item { transition: none; }
  .bkw-since .bkw-since__warn li, .bkw-since .bkw-since__item > .bkw-since__more { animation: none; }
  .bkw-since .bkw-since__pr::after { transition: none; }
}

js:
// Quarry changelog. The DOM is the data: each entry carries its type, each release its
// version. Picking "I'm on" or a type toggle recounts everything and FLIPs the entries that
// stay visible, so nothing jumps.
const radios = Array.from(root.querySelectorAll(".bkw-since__vs input"));
const toggles = Array.from(root.querySelectorAll(".bkw-since__fs input"));
const rels = Array.from(root.querySelectorAll(".bkw-since__rel"));
const items = Array.from(root.querySelectorAll(".bkw-since__item"));
const nEl = root.querySelector(".bkw-since__n");
const srOut = root.querySelector(".bkw-since__sr");
const segs = Array.from(root.querySelectorAll(".bkw-since__bar i"));
const warn = root.querySelector(".bkw-since__warn");
const warnHead = root.querySelector(".bkw-since__wh");
const warnList = root.querySelector(".bkw-since__wl");
const cmd = root.querySelector(".bkw-since__cmdt");
const copy = root.querySelector(".bkw-since__copy");
const empty = root.querySelector(".bkw-since__empty");
const log = root.querySelector(".bkw-since__log");
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const LATEST = rels[0].dataset.v;

const uid = Math.random().toString(36).slice(2, 7);
radios.forEach((r) => { r.name = "bkw-since-v-" + uid; });

const cmpV = (a, b) => {
  const x = a.split(".").map(Number), y = b.split(".").map(Number);
  for (let i = 0; i < Math.max(x.length, y.length); i++) { const d = (x[i] || 0) - (y[i] || 0); if (d) return d; }
  return 0;
};
const relOf = (el) => el.closest(".bkw-since__rel").dataset.v;

function apply(animate) {
  const mine = (radios.find((r) => r.checked) || radios[0]).value;
  const on = new Set(toggles.filter((t) => t.checked).map((t) => t.value));

  // FLIP: first
  const first = new Map();
  if (animate && !reduce) [...items, ...rels.map((r) => r.querySelector("h3"))].forEach((el) => {
    if (el.offsetParent) first.set(el, el.getBoundingClientRect().top);
  });

  const counts = { feat: 0, fix: 0, perf: 0, break: 0 };
  const breaking = [];
  items.forEach((it) => {
    const newer = cmpV(relOf(it), mine) > 0;
    const t = it.dataset.type;
    if (newer) {
      counts[t]++;
      if (t === "break") breaking.push([relOf(it), it.querySelector("h4").textContent, it.querySelector("p").innerHTML]);
    }
    it.hidden = !on.has(t);
  });
  let shown = 0;
  rels.forEach((r) => {
    const c = cmpV(r.dataset.v, mine);
    r.dataset.state = c > 0 ? "new" : c === 0 ? "current" : "have";
    r.querySelector(".bkw-since__state").textContent = c > 0 ? "New to you" : c === 0 ? "Your version" : "Installed";
    const vis = Array.from(r.querySelectorAll(".bkw-since__item")).some((i) => !i.hidden);
    r.hidden = !vis;
    if (vis) shown++;
  });
  empty.hidden = shown > 0;

  // numbers: the total counts only types you are showing
  const total = Object.keys(counts).reduce((s, k) => s + (on.has(k) ? counts[k] : 0), 0);
  nEl.style.setProperty("--bkw-since-n", String(total));
  srOut.textContent = total + " changes between " + mine + " and " + LATEST;
  root.querySelectorAll("[data-count]").forEach((b) => { b.textContent = String(counts[b.dataset.count]); });
  segs.forEach((s) => {
    s.style.setProperty("--c", String(counts[s.dataset.seg]));
    if (on.has(s.dataset.seg)) s.removeAttribute("data-off"); else s.setAttribute("data-off", "");
  });

  // the upgrade checklist
  warnList.replaceChildren(...breaking.reverse().map(([v, title, body], i) => {
    const li = document.createElement("li");
    li.style.setProperty("--i", String(i));
    const b = document.createElement("b");
    b.textContent = title + " (" + v + ")";
    li.append(b, document.createElement("br"));
    const span = document.createElement("span");
    span.innerHTML = body;
    li.append(span);
    return li;
  }));
  const clear = breaking.length === 0;
  warn.classList.toggle("is-clear", clear);
  warnHead.textContent = mine === LATEST ? "You are up to date" : clear ? "No breaking changes. Upgrade freely." : breaking.length + " breaking change" + (breaking.length > 1 ? "s" : "") + " before you upgrade";
  cmd.textContent = mine === LATEST ? "quarry --version  # " + LATEST + ".0" : "quarry upgrade --from " + mine;

  // FLIP: last, invert, play
  if (!first.size) return;
  first.forEach((top, el) => {
    if (!el.offsetParent) return;
    const dy = top - el.getBoundingClientRect().top;
    if (Math.abs(dy) < 1) return;
    el.animate([{ transform: "translateY(" + dy + "px)" }, { transform: "none" }], { duration: 520, easing: "cubic-bezier(.2, .9, .25, 1)" });
  });
  items.forEach((el, i) => {
    if (el.hidden || first.has(el)) return;
    el.animate([{ opacity: 0, transform: "translateX(-10px)" }, { opacity: 1, transform: "none" }], { duration: 360, delay: (i % 4) * 40, easing: "cubic-bezier(.2, .9, .25, 1)", fill: "backwards" });
  });
}

radios.forEach((r) => r.addEventListener("change", () => apply(true)));
toggles.forEach((t) => t.addEventListener("change", () => apply(true)));
// each pull-request number opens that change's details in place, under its entry
root.querySelectorAll(".bkw-since__pr").forEach((b, i) => {
  const more = b.nextElementSibling;
  more.id = "bkw-since-pr-" + uid + "-" + i;
  b.setAttribute("aria-controls", more.id);
  b.setAttribute("aria-label", "Pull request " + b.textContent.trim() + ", details");
  b.addEventListener("click", () => {
    const open = b.getAttribute("aria-expanded") !== "true";
    b.setAttribute("aria-expanded", String(open));
    more.hidden = !open;
  });
});
copy.addEventListener("click", async () => {
  const text = cmd.textContent;
  let ok = false;
  try { if (navigator.clipboard) { await navigator.clipboard.writeText(text); ok = true; } } catch (e) { ok = false; }
  copy.textContent = ok ? "Copied" : "Select";
  if (!ok) { const sel = getSelection(); const rg = document.createRange(); rg.selectNodeContents(cmd); sel.removeAllRanges(); sel.addRange(rg); }
  setTimeout(() => { if (root.isConnected) copy.textContent = "Copy"; }, 1400);
});
apply(false);

