/* Sprout — an isometric shelf of live screens. Re-theme: --bkw-stack-bg, -ink, -leaf, -coral. */
.bkw-stack {
  --bkw-stack-bg: oklch(0.965 0.03 105);
  --bkw-stack-ink: oklch(0.27 0.05 160);
  --bkw-stack-leaf: oklch(0.63 0.15 148);
  --bkw-stack-coral: oklch(0.72 0.15 35);
  --bkw-stack-mute: color-mix(in oklch, var(--bkw-stack-ink) 62%, var(--bkw-stack-bg));
  --bkw-stack-line: color-mix(in oklch, var(--bkw-stack-ink) 12%, transparent);
  --bkw-stack-round: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", sans-serif;
  --bkw-stack-spring: linear(0, 0.034, 0.116, 0.228, 0.35, 0.476, 0.593, 0.699, 0.789, 0.865, 0.924, 0.97, 1.002, 1.025, 1.039, 1.046, 1.048, 1.046, 1.042, 1.037, 1.031, 1.025, 1.02, 1.015, 1.01, 1.007, 1.004, 1.002, 1, 0.999, 0.998, 0.998, 0.998, 0.998, 0.998, 0.998, 1);
  --bkw-stack-soft: linear(0, 0.024, 0.082, 0.159, 0.247, 0.337, 0.427, 0.509, 0.587, 0.655, 0.717, 0.769, 0.815, 0.853, 0.885, 0.911, 0.933, 0.949, 0.963, 0.974, 0.982, 0.989, 0.993, 0.997, 0.999, 1.001, 1.002, 1.003, 1.003, 1.003, 1.003, 1.003, 1.003, 1.002, 1.002, 1.002, 1);

  container-type: inline-size;
  container-name: bkw-stack;
  position: relative; box-sizing: border-box; width: 100%; overflow: hidden; border-radius: 28px;
  background:
    radial-gradient(40% 50% at 92% 18%, color-mix(in oklch, var(--bkw-stack-coral) 22%, transparent), transparent 70%),
    radial-gradient(45% 55% at 70% 95%, color-mix(in oklch, var(--bkw-stack-leaf) 20%, transparent), transparent 70%),
    var(--bkw-stack-bg);
  color: var(--bkw-stack-ink);
  font-family: var(--bkw-stack-round);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 3px solid var(--bkw-stack-leaf); outline-offset: 3px; }
}
.bkw-stack__in { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "stage"; gap: 10px; padding: clamp(20px, 4.4cqi, 54px); }

.bkw-stack__copy { grid-area: copy; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; }
.bkw-stack__brand {
  display: inline-flex; align-items: center; gap: 6px; font-weight: 800; font-size: 20px; letter-spacing: -.02em;
  & svg { width: 32px; height: 32px; fill: none; stroke-linecap: round; stroke-linejoin: round; }
  & .s { stroke: var(--bkw-stack-ink); stroke-width: 2.4; }
  & .l1 { fill: var(--bkw-stack-leaf); } & .l2 { fill: color-mix(in oklch, var(--bkw-stack-leaf), white 30%); }
}
.bkw-stack__title { margin: 22px 0 0; max-width: 12ch; font-size: clamp(2.1rem, 1.2rem + 3.8cqi, 3.6rem); line-height: .98; letter-spacing: -.04em; font-weight: 850; text-wrap: balance; }
.bkw-stack__lede { margin: 16px 0 0; max-width: 40ch; font-size: clamp(15px, 14px + .3cqi, 17px); line-height: 1.55; color: var(--bkw-stack-mute); text-wrap: pretty; font-family: system-ui, sans-serif; }

.bkw-stack__tabs { margin-top: 22px; width: calc(100% + 8px); display: flex; gap: 8px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding: 4px; margin-inline: -4px;
  -webkit-mask: linear-gradient(90deg, black 85%, transparent); mask: linear-gradient(90deg, black 85%, transparent); }
.bkw-stack__tab {
  position: relative; flex: 0 0 auto; scroll-snap-align: start; overflow: hidden;
  display: grid; grid-template-columns: auto 1fr; align-items: center; gap: 0 10px; padding: 10px 14px 10px 10px; border: 0; border-radius: 16px; cursor: pointer;
  background: color-mix(in oklch, white 55%, transparent); color: var(--bkw-stack-ink); text-align: start; font: inherit;
  box-shadow: inset 0 0 0 1.5px var(--bkw-stack-line);
  transition: background-color .3s, box-shadow .3s, scale .4s var(--bkw-stack-soft);
  & svg { grid-row: span 2; width: 34px; height: 34px; padding: 7px; border-radius: 11px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; background: color-mix(in oklch, var(--bkw-stack-leaf) 14%, transparent); color: var(--bkw-stack-leaf); transition: background-color .3s, color .3s; }
  & b { font-size: 15px; font-weight: 800; letter-spacing: -.01em; }
  & span { display: none; font: 13.5px/1.4 system-ui, sans-serif; color: var(--bkw-stack-mute); text-wrap: pretty; }
  &:hover { background: color-mix(in oklch, white 80%, transparent); }
  &:active { scale: .98; }
  &[aria-selected="true"] { background: white; box-shadow: inset 0 0 0 2px var(--bkw-stack-ink), 0 10px 24px -14px color-mix(in oklch, var(--bkw-stack-ink) 60%, transparent); }
  &[aria-selected="true"] svg { background: var(--bkw-stack-leaf); color: white; }
}
.bkw-stack__prog {
  position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: var(--bkw-stack-leaf); transform-origin: left; scale: 0 1; opacity: 0;
}
.bkw-stack.is-auto .bkw-stack__tab[aria-selected="true"] .bkw-stack__prog { opacity: 1; animation: bkw-stack-prog 5.2s linear forwards; }
.bkw-stack.is-auto:is(:hover, :focus-within, .is-paused) .bkw-stack__tab[aria-selected="true"] .bkw-stack__prog { animation-play-state: paused; }
@keyframes bkw-stack-prog { from { scale: 0 1; } to { scale: 1 1; } }
.bkw-stack__rate { margin: 18px 0 0; font: 13px/1.4 system-ui, sans-serif; color: var(--bkw-stack-mute); & b { color: var(--bkw-stack-ink); font-weight: 750; } & span { color: var(--bkw-stack-coral); letter-spacing: .05em; } }

/* ---------- the shelf ---------- */
.bkw-stack__stage {
  grid-area: stage; position: relative; min-width: 0; height: 480px; container-type: inline-size; container-name: bkw-stack-stage;
  perspective: 1500px; perspective-origin: 50% 40%; outline-offset: -4px; border-radius: 22px;
}
.bkw-stack__floor {
  position: absolute; left: 50%; top: 60%; width: 120cqi; height: 160px; translate: -50% -50%; border-radius: 50%;
  background: radial-gradient(closest-side, color-mix(in oklch, var(--bkw-stack-leaf) 18%, transparent), transparent);
}
.bkw-stack__shelf { position: absolute; inset: 0; }
.bkw-stack__ph {
  /* lying in its slot on the shelf */
  --x: calc(-2cqi + var(--i) * 9.5cqi);
  --y: calc(196px - var(--i) * 54px);
  --z: 0px; --rx: 56deg; --rz: -42deg; --sc: .5;
  position: absolute; left: 50%; top: 50%; width: 216px; height: 440px; margin: -220px 0 0 -108px;
  z-index: calc(10 - var(--i));
  padding: 7px; border-radius: 38px; cursor: pointer;
  background: var(--bkw-stack-ink);
  box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--bkw-stack-ink), white 25%) inset, 30px 40px 40px -10px color-mix(in oklch, var(--bkw-stack-ink) 35%, transparent);
  transform: translate3d(var(--x), var(--y), var(--z)) rotateX(var(--rx)) rotateZ(var(--rz)) scale(var(--sc));
  transition: transform 1s var(--bkw-stack-spring), box-shadow .8s ease-out, filter .4s;
  transition-delay: 0s;
  &:hover:not(.is-up) { filter: brightness(1.04) saturate(1.08); --z: 14px; }
}
.bkw-stack__ph.is-up {
  --x: -24cqi; --y: -6px; --z: 80px; --rx: 0deg; --rz: 0deg; --sc: .9;
  z-index: 20; cursor: default;
  box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--bkw-stack-ink), white 25%) inset, 0 50px 70px -30px color-mix(in oklch, var(--bkw-stack-ink) 60%, transparent);
  transition-delay: .07s;
}
.bkw-stack__scr {
  position: relative; height: 100%; overflow: hidden; border-radius: 31px; padding: 40px 14px 14px;
  background: oklch(0.985 0.012 110); color: var(--bkw-stack-ink); font: 12px/1.35 var(--bkw-stack-round);
  display: flex; flex-direction: column; gap: 10px;
}
.bkw-stack__bar { position: absolute; top: 12px; left: 22px; right: 22px; display: flex; justify-content: space-between; align-items: center; font-size: 11.5px;
  & i { width: 62px; height: 18px; border-radius: 99px; background: var(--bkw-stack-ink); position: absolute; left: 50%; translate: -50% 0; top: -2px; } }
.bkw-stack__sh { display: grid; gap: 1px; & span { font-size: 11px; color: var(--bkw-stack-mute); } & b { font-size: 19px; font-weight: 850; letter-spacing: -.02em; line-height: 1.1; } }

.bkw-stack__todo { list-style: none; margin: 0; padding: 0; display: grid; gap: 7px;
  & li { display: grid; grid-template-columns: 30px 1fr auto; align-items: center; gap: 8px; padding: 8px; border-radius: 14px; background: white; box-shadow: 0 1px 0 var(--bkw-stack-line); }
  & i { width: 30px; height: 30px; border-radius: 10px; background: radial-gradient(circle at 35% 30%, color-mix(in oklch, var(--c), white 30%), var(--c)); }
  & div { display: grid; min-width: 0; } & b { font-size: 13px; } & span { font-size: 10.5px; color: var(--bkw-stack-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em { font-style: normal; font-size: 10px; font-weight: 700; padding: 3px 7px; border-radius: 99px; background: color-mix(in oklch, var(--bkw-stack-leaf) 15%, white); color: color-mix(in oklch, var(--bkw-stack-leaf), black 25%); }
  & .is-late em { background: color-mix(in oklch, var(--bkw-stack-coral) 20%, white); color: color-mix(in oklch, var(--bkw-stack-coral), black 30%); }
  & .is-done { opacity: .55; } & .is-done b { text-decoration: line-through; }
}
.bkw-stack__streak { margin-top: auto; display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 16px; background: var(--bkw-stack-ink); color: white;
  & b { font-size: 26px; font-weight: 850; letter-spacing: -.03em; } & span { font-size: 11px; line-height: 1.3; opacity: .85; } }

.bkw-stack__huge { margin: 6px 0 0; font-size: 64px; font-weight: 850; line-height: .9; letter-spacing: -.05em; font-variant-numeric: tabular-nums; color: var(--bkw-stack-coral); & small { font-size: 28px; } }
.bkw-stack__note { margin: 0; font-size: 12px; color: var(--bkw-stack-mute); text-wrap: pretty; }
.bkw-stack__chart { width: 100%; height: auto; margin-top: 6px;
  & .a { fill: color-mix(in oklch, var(--bkw-stack-leaf) 16%, transparent); } & .l { fill: none; stroke: var(--bkw-stack-leaf); stroke-width: 2.4; stroke-linejoin: round; }
  & .t { stroke: var(--bkw-stack-coral); stroke-dasharray: 4 3; stroke-width: 1.4; } & text { font: 700 9px var(--bkw-stack-round); fill: var(--bkw-stack-coral); }
  & circle { fill: var(--bkw-stack-coral); stroke: white; stroke-width: 2; } }
.bkw-stack__legend { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--bkw-stack-mute); }

.bkw-stack__scr--scan { background: oklch(0.3 0.04 160); color: white; padding-inline: 10px; }
.bkw-stack__scr--scan .bkw-stack__bar i { background: black; }
.bkw-stack__cam { position: relative; flex: 1; border-radius: 22px; overflow: hidden; display: grid; place-items: center;
  background: radial-gradient(circle at 50% 45%, oklch(0.5 0.08 150), oklch(0.26 0.05 160));
  & svg { width: 82%; }
  & .leaf { fill: oklch(0.42 0.1 150); } & .vein { fill: none; stroke: oklch(0.78 0.08 130); stroke-width: 3.2; stroke-linecap: round; opacity: .8; }
  & .cnr { fill: none; stroke: white; stroke-width: 4; stroke-linecap: round; } }
.bkw-stack__scanline { position: absolute; left: 8%; right: 8%; top: 20%; height: 2px; border-radius: 2px; background: var(--bkw-stack-coral); box-shadow: 0 0 12px 2px var(--bkw-stack-coral); animation: bkw-stack-scan 2.6s cubic-bezier(.45, 0, .55, 1) infinite alternate; }
@keyframes bkw-stack-scan { to { translate: 0 210px; } }
.bkw-stack__match { padding: 12px; border-radius: 18px; background: white; color: var(--bkw-stack-ink);
  & b { display: block; font-size: 15px; font-weight: 850; } & span { font-size: 11px; font-weight: 700; color: var(--bkw-stack-leaf); } & p { margin: 6px 0 0; font-size: 11px; color: var(--bkw-stack-mute); } }

.bkw-stack__gauge { width: 100%; margin-top: 8px;
  & .arc { fill: none; stroke: var(--bkw-stack-line); stroke-width: 12; stroke-linecap: round; }
  & .good { fill: none; stroke: color-mix(in oklch, var(--bkw-stack-leaf) 55%, white); stroke-width: 12; }
  & .tk line { stroke: var(--bkw-stack-ink); stroke-width: 1.2; opacity: .4; }
  & .needle { stroke: var(--bkw-stack-coral); stroke-width: 3.5; stroke-linecap: round; } & circle { fill: var(--bkw-stack-ink); } }
.bkw-stack__lux { margin: -4px 0 0; text-align: center; font-size: 13px; color: var(--bkw-stack-mute); & b { display: block; font-size: 40px; font-weight: 850; letter-spacing: -.04em; color: var(--bkw-stack-ink); line-height: 1; font-variant-numeric: tabular-nums; } }
.bkw-stack__fit { list-style: none; margin: 4px 0 0; padding: 0; display: flex; flex-wrap: wrap; gap: 5px; justify-content: center;
  & li { padding: 4px 9px; border-radius: 99px; font-size: 11px; font-weight: 700; }
  & .y { background: color-mix(in oklch, var(--bkw-stack-leaf) 16%, white); color: color-mix(in oklch, var(--bkw-stack-leaf), black 30%); }
  & .n { background: color-mix(in oklch, var(--bkw-stack-coral) 18%, white); color: color-mix(in oklch, var(--bkw-stack-coral), black 30%); text-decoration: line-through; } }

.bkw-stack__days { list-style: none; margin: 4px 0 0; padding: 0; display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; text-align: center;
  & li { display: grid; gap: 3px; padding: 6px 0; border-radius: 12px; font-size: 9.5px; color: var(--bkw-stack-mute); background: white; }
  & b { font-size: 13px; color: var(--bkw-stack-ink); }
  & .w { background: var(--bkw-stack-leaf); color: white; } & .w b { color: white; } }
.bkw-stack__sitter { display: flex; align-items: center; gap: 10px; padding: 10px; border-radius: 16px; background: white;
  & > span { width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; font-weight: 800; color: white; background: var(--bkw-stack-coral); }
  & div { display: grid; } & b { font-size: 13.5px; } & small { font-size: 10.5px; color: var(--bkw-stack-mute); } }

/* ---------- layout ---------- */
@container bkw-stack (min-width: 900px) {
  .bkw-stack__in { grid-template-columns: minmax(300px, .82fr) minmax(0, 1.18fr); grid-template-areas: "copy stage"; gap: 24px; align-items: center; }
  .bkw-stack__tabs { flex-direction: column; overflow: visible; gap: 6px; -webkit-mask: none; mask: none; }
  .bkw-stack__tab { grid-template-columns: auto 1fr; padding: 12px 16px 12px 12px; }
  .bkw-stack__tab span { display: block; grid-column: 2; }
  .bkw-stack__stage { height: 600px; }
}
@container bkw-stack-stage (max-width: 560px) {
  /* narrow: the standing phone takes the middle, the shelf becomes a row of coasters below it */
  .bkw-stack__ph { --x: calc((var(--i) - 2) * 19cqi); --y: 178px; --rx: 62deg; --rz: -30deg; --sc: .28; }
  .bkw-stack__ph.is-up { --x: 0cqi; --y: -42px; --sc: .78; --z: 40px; }
  .bkw-stack__floor { top: 86%; height: 90px; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-stack .bkw-stack__ph { transition: opacity .25s linear; }
  .bkw-stack .bkw-stack__scanline { animation: none; translate: 0 100px; }
  .bkw-stack .bkw-stack__tab, .bkw-stack .bkw-stack__tab svg { transition: none; }
}

