// Sprout shelf. Tabs follow the ARIA tablist pattern; the stage is the tabpanel. Choosing a
// screen only toggles .is-up — the transform list is shared, so CSS springs lying to standing.
// Autoplay advances on the progress bar's animationend, so pausing is just animation-play-state.
const tabs = Array.from(root.querySelectorAll(".bkw-stack__tab"));
const phones = Array.from(root.querySelectorAll(".bkw-stack__ph"));
const stage = root.querySelector(".bkw-stack__stage");
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const NAMES = tabs.map((t) => t.querySelector("b").textContent);
const uid = Math.random().toString(36).slice(2, 7);
stage.id = "bkw-stack-panel-" + uid;
tabs.forEach((t, i) => { t.id = "bkw-stack-tab-" + uid + "-" + i; t.setAttribute("aria-controls", stage.id); });

let cur = -1;
function select(i, focus) {
  i = (i + tabs.length) % tabs.length;
  if (i === cur) return;
  cur = i;
  tabs.forEach((t, j) => { t.setAttribute("aria-selected", String(j === i)); t.tabIndex = j === i ? 0 : -1; });
  phones.forEach((p, j) => p.classList.toggle("is-up", j === i));
  stage.setAttribute("aria-labelledby", tabs[i].id);
  stage.setAttribute("aria-label", NAMES[i] + " screen");
  if (focus) tabs[i].focus();
  const strip = tabs[i].parentElement;
  if (strip.scrollWidth > strip.clientWidth + 2) {
    strip.scrollTo({ left: tabs[i].offsetLeft - strip.offsetLeft - 4, behavior: reduce ? "auto" : "smooth" });
  }
}
const stopAuto = () => root.classList.remove("is-auto");
tabs.forEach((t, i) => {
  t.addEventListener("click", () => { stopAuto(); select(i); });
  t.addEventListener("keydown", (e) => {
    const k = e.key;
    let j = null;
    if (k === "ArrowDown" || k === "ArrowRight") j = i + 1;
    else if (k === "ArrowUp" || k === "ArrowLeft") j = i - 1;
    else if (k === "Home") j = 0;
    else if (k === "End") j = tabs.length - 1;
    if (j === null) return;
    e.preventDefault();
    stopAuto();
    select(j, true);
  });
  // the progress bar finishing is the autoplay clock
  t.querySelector(".bkw-stack__prog").addEventListener("animationend", () => {
    if (root.classList.contains("is-auto") && cur === i) select(i + 1);
  });
});
phones.forEach((p, i) => p.addEventListener("click", () => { if (cur !== i) { stopAuto(); select(i); } }));
stage.addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight") { e.preventDefault(); stopAuto(); select(cur + 1); }
  else if (e.key === "ArrowLeft") { e.preventDefault(); stopAuto(); select(cur - 1); }
});

// pause when off screen or in a hidden tab
const setPaused = () => root.classList.toggle("is-paused", !visible || document.hidden);
let visible = true;
const io = new IntersectionObserver((ents) => {
  if (!root.isConnected) { io.disconnect(); document.removeEventListener("visibilitychange", onVis); return; }
  visible = ents[ents.length - 1].isIntersecting;
  setPaused();
}, { threshold: 0.25 });
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener("visibilitychange", onVis); io.disconnect(); return; }
  setPaused();
};
document.addEventListener("visibilitychange", onVis);
io.observe(root);

if (!reduce) root.classList.add("is-auto");
select(0);

