/* Linework — code on the left, a live sequence diagram on the right.
   Re-theme: --bkw-seq-paper, -ink, -accent, -editor. */
.bkw-seq {
  --bkw-seq-paper: oklch(0.975 0.006 240);
  --bkw-seq-ink: oklch(0.26 0.03 255);
  --bkw-seq-accent: oklch(0.67 0.18 48);
  --bkw-seq-editor: oklch(0.21 0.02 255);
  --bkw-seq-line: color-mix(in oklch, var(--bkw-seq-ink) 14%, transparent);
  --bkw-seq-mute: color-mix(in oklch, var(--bkw-seq-ink) 60%, var(--bkw-seq-paper));
  --bkw-seq-ed-ink: oklch(0.9 0.01 250);
  --bkw-seq-ed-mute: color-mix(in oklch, var(--bkw-seq-ed-ink) 45%, var(--bkw-seq-editor));
  --bkw-seq-tk-kw: color-mix(in oklch, var(--bkw-seq-accent), white 18%);
  --bkw-seq-tk-name: oklch(0.83 0.09 185);
  --bkw-seq-tk-arrow: oklch(0.88 0.14 95);
  --bkw-seq-err: oklch(0.68 0.2 25);
  --bkw-seq-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --bkw-seq-spring: linear(0, 0.028, 0.094, 0.183, 0.284, 0.387, 0.491, 0.585, 0.669, 0.743, 0.807, 0.861, 0.904, 0.938, 0.964, 0.984, 0.999, 1.009, 1.015, 1.019, 1.021, 1.021, 1.02, 1.018, 1.016, 1.014, 1.012, 1.01, 1.008, 1.006, 1.005, 1.003, 1.002, 1.002, 1.001, 1.001, 1);
  --bkw-seq-out: cubic-bezier(.2, .8, .2, 1);

  container-type: inline-size;
  container-name: bkw-seq;
  position: relative; box-sizing: border-box; width: 100%; border-radius: 22px; overflow: hidden;
  color: var(--bkw-seq-ink);
  background:
    linear-gradient(color-mix(in oklch, var(--bkw-seq-ink) 5%, transparent) 1px, transparent 1px) 0 0 / 24px 24px,
    linear-gradient(90deg, color-mix(in oklch, var(--bkw-seq-ink) 5%, transparent) 1px, transparent 1px) 0 0 / 24px 24px,
    var(--bkw-seq-paper);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 2px solid var(--bkw-seq-accent); outline-offset: 3px; }
}
.bkw-seq__in { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "ide"; gap: 26px; padding: clamp(20px, 4.4cqi, 54px); }

.bkw-seq__head { grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; justify-items: start; }
.bkw-seq__brand {
  display: inline-flex; align-items: center; gap: 8px; font-weight: 700; font-size: 16px;
  & svg { width: 26px; height: 26px; fill: none; stroke: var(--bkw-seq-ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & .a { stroke: var(--bkw-seq-accent); }
}
.bkw-seq__eyebrow { margin: 14px 0 0; font: 600 12px/1 var(--bkw-seq-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--bkw-seq-accent); }
.bkw-seq__title { margin: 0; max-width: 18ch; font-size: clamp(1.95rem, 1.1rem + 3.3cqi, 3.1rem); line-height: 1.02; letter-spacing: -.04em; font-weight: 720; text-wrap: balance; }
.bkw-seq__lede { margin: 0; max-width: 54ch; font-size: clamp(14.5px, 13.8px + .25cqi, 16.5px); line-height: 1.6; color: var(--bkw-seq-mute); text-wrap: pretty; }
.bkw-seq__ex {
  display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px;
  & button { padding: 8px 13px; border-radius: 999px; border: 1px solid var(--bkw-seq-line); background: color-mix(in oklch, white 60%, transparent); color: var(--bkw-seq-ink); font: 600 13px/1 system-ui, sans-serif; cursor: pointer; transition: background-color .2s, color .2s, border-color .2s; }
  & button:hover { border-color: color-mix(in oklch, var(--bkw-seq-ink) 35%, transparent); }
  & button[aria-pressed="true"] { background: var(--bkw-seq-ink); color: var(--bkw-seq-paper); border-color: var(--bkw-seq-ink); }
}

.bkw-seq__ide { grid-area: ide; display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; min-width: 0; }

/* ---------- editor ---------- */
.bkw-seq__ed {
  min-width: 0; display: flex; flex-direction: column; border-radius: 16px; overflow: hidden; background: var(--bkw-seq-editor); color: var(--bkw-seq-ed-ink);
  box-shadow: 0 30px 60px -34px color-mix(in oklch, var(--bkw-seq-ink) 70%, transparent);
}
.bkw-seq__bar {
  display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-bottom: 1px solid color-mix(in oklch, var(--bkw-seq-ed-ink) 10%, transparent);
  font: 500 12px/1 var(--bkw-seq-mono);
  & .bkw-seq__file { font-weight: 600; }
}
.bkw-seq__dots { display: flex; gap: 6px; & i { width: 10px; height: 10px; border-radius: 50%; background: color-mix(in oklch, var(--bkw-seq-ed-ink) 18%, transparent); } }
.bkw-seq__hint { margin-left: auto; padding: 3px 7px; border-radius: 5px; color: var(--bkw-seq-editor); background: var(--bkw-seq-tk-arrow); font-weight: 700; transition: opacity .3s; }
.bkw-seq__ed:focus-within .bkw-seq__hint, .bkw-seq.is-edited .bkw-seq__hint { opacity: 0; }

.bkw-seq__code { --lh: 22px; position: relative; flex: 1; display: grid; grid-template-columns: auto minmax(0, 1fr); font: 13px/var(--lh) var(--bkw-seq-mono); }
.bkw-seq__gut {
  list-style: none; margin: 0; padding: 12px 10px 12px 14px; text-align: end; color: var(--bkw-seq-ed-mute); font-variant-numeric: tabular-nums; user-select: none;
  & li { position: relative; height: var(--lh); }
  & li.is-err::before { content: ""; position: absolute; left: -8px; top: 50%; width: 6px; height: 6px; margin-top: -3px; border-radius: 50%; background: var(--bkw-seq-err); }
  & li.is-cur { color: var(--bkw-seq-ed-ink); }
}
.bkw-seq__wrap { position: relative; display: grid; min-width: 0; overflow: hidden; }
.bkw-seq__hl, .bkw-seq__ta {
  grid-area: 1 / 1; margin: 0; padding: 12px 16px 12px 6px; border: 0; font: inherit; line-height: var(--lh); letter-spacing: 0; tab-size: 2;
  white-space: pre; overflow-wrap: normal; word-break: normal;
}
.bkw-seq__hl { pointer-events: none; color: var(--bkw-seq-ed-ink); overflow: hidden;
  & .ln { display: inline-block; vertical-align: top; min-width: 100%; border-radius: 3px; transition: background-color .2s; }
  & .ln.is-hot { background: color-mix(in oklch, var(--bkw-seq-accent) 26%, transparent); }
  & .ln.is-cur { background: color-mix(in oklch, var(--bkw-seq-ed-ink) 6%, transparent); }
  & .kw { color: var(--bkw-seq-tk-kw); font-weight: 600; }
  & .nm { color: var(--bkw-seq-tk-name); }
  & .ar { color: var(--bkw-seq-tk-arrow); font-weight: 700; }
  & .pc { color: var(--bkw-seq-ed-mute); }
  & .cm { color: var(--bkw-seq-ed-mute); font-style: italic; }
  & .er { text-decoration: underline wavy var(--bkw-seq-err); text-decoration-skip-ink: none; text-underline-offset: 4px; }
}
.bkw-seq__ta {
  resize: none; outline: none; overflow-x: auto; overflow-y: hidden; background: transparent; color: transparent; caret-color: var(--bkw-seq-accent);
  scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--bkw-seq-ed-ink) 25%, transparent) transparent;
  &::selection { background: color-mix(in oklch, var(--bkw-seq-tk-name) 30%, transparent); color: transparent; }
}
.bkw-seq__wrap:has(.bkw-seq__ta:focus-visible) { box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--bkw-seq-accent) 60%, transparent); border-radius: 6px; }
.bkw-seq__status {
  margin: 0; display: flex; align-items: center; gap: 8px; padding: 9px 14px; border-top: 1px solid color-mix(in oklch, var(--bkw-seq-ed-ink) 10%, transparent);
  font: 500 12px/1.4 var(--bkw-seq-mono); color: var(--bkw-seq-ed-mute);
  &::before { content: ""; width: 8px; height: 8px; flex: none; border-radius: 50%; background: oklch(0.75 0.15 150); box-shadow: 0 0 0 3px color-mix(in oklch, oklch(0.75 0.15 150) 25%, transparent); }
  &.is-err { color: color-mix(in oklch, var(--bkw-seq-err), white 25%); }
  &.is-err::before { background: var(--bkw-seq-err); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkw-seq-err) 25%, transparent); }
}

/* ---------- output ---------- */
.bkw-seq__out { margin: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 16px; background: color-mix(in oklch, white 82%, var(--bkw-seq-paper)); border: 1px solid var(--bkw-seq-line); overflow: hidden; }
.bkw-seq__cap { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 12px; padding: 12px 16px; border-bottom: 1px solid var(--bkw-seq-line);
  & b { font-size: 14px; font-weight: 650; } }
.bkw-seq__meta { font: 500 11.5px/1 var(--bkw-seq-mono); color: var(--bkw-seq-mute); font-variant-numeric: tabular-nums; }
.bkw-seq__canvas { flex: 1; overflow-x: auto; overscroll-behavior-x: contain; padding: 8px 6px; display: grid; align-items: start; scrollbar-width: thin; }
.bkw-seq__svg {
  display: block; width: 100%; height: auto;
  & text { font: 12px system-ui, -apple-system, sans-serif; fill: var(--bkw-seq-ink); }
  & .pbox { fill: white; stroke: var(--bkw-seq-ink); stroke-width: 1.4; }
  & .pname { font-weight: 650; font-size: 12.5px; }
  & .life { stroke: color-mix(in oklch, var(--bkw-seq-ink) 35%, transparent); stroke-dasharray: 3 4; }
  & .actor circle { fill: var(--bkw-seq-accent); }
  & .actor path { fill: none; stroke: var(--bkw-seq-ink); stroke-width: 1.6; stroke-linecap: round; }
  & .msg line, & .msg path.loop { stroke: var(--bkw-seq-ink); stroke-width: 1.5; fill: none; transform-box: fill-box; }
  & .msg.ret line, & .msg.ret path.loop { stroke-dasharray: 5 4; }
  & .msg .head { fill: var(--bkw-seq-ink); stroke: none; }
  & .msg.ret .head { fill: none; stroke: var(--bkw-seq-ink); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & .msg text { font-size: 11.5px; }
  & .msg .hit { stroke: transparent; stroke-width: 16; fill: none; }
  & .note rect { transform-box: fill-box; fill: oklch(0.95 0.07 95); stroke: color-mix(in oklch, oklch(0.75 0.12 85), black 10%); stroke-width: 1; }
  & .note text { font-size: 11px; font-style: italic; }
  & [data-line] { cursor: pointer; }
  & [data-line] text, & [data-line] line, & [data-line] .head, & [data-line] path { transition: fill .2s, stroke .2s; }
  & [data-line].is-hot line, & [data-line].is-hot path.loop { stroke: var(--bkw-seq-accent); stroke-width: 2.2; }
  & [data-line].is-hot .head { fill: var(--bkw-seq-accent); }
  & .msg.ret.is-hot .head { fill: none; stroke: var(--bkw-seq-accent); }
  & [data-line].is-hot text { fill: color-mix(in oklch, var(--bkw-seq-accent), black 25%); font-weight: 650; }
  & .note.is-hot rect { stroke: var(--bkw-seq-accent); stroke-width: 2; }
}

@container bkw-seq (min-width: 920px) {
  .bkw-seq__in { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "head head" "ide ide"; }
  .bkw-seq__head { grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); grid-template-areas: "brand brand" "eyebrow eyebrow" "title lede" "title ex"; column-gap: 48px; align-items: end; }
  .bkw-seq__brand { grid-area: brand; } .bkw-seq__eyebrow { grid-area: eyebrow; } .bkw-seq__title { grid-area: title; } .bkw-seq__lede { grid-area: lede; } .bkw-seq__ex { grid-area: ex; }
