// Linework: parse -> highlight -> draw. The textarea is the only input; the <pre> behind it
// mirrors its text with tokens wrapped, so the caret, selection and IME stay native.
const ta = root.querySelector(".bkw-seq__ta");
const hl = root.querySelector(".bkw-seq__hl");
const gut = root.querySelector(".bkw-seq__gut");
const svg = root.querySelector(".bkw-seq__svg");
const status = root.querySelector(".bkw-seq__status");
const meta = root.querySelector(".bkw-seq__meta");
const dtitle = root.querySelector(".bkw-seq__dtitle");
const file = root.querySelector(".bkw-seq__file");
const exBtns = Array.from(root.querySelectorAll(".bkw-seq__ex button"));
const sources = Array.from(root.querySelectorAll(".bkw-seq__src")).map((t) => t.content.textContent);
const FILES = ["checkout.seq", "passkey.seq", "webhook-retry.seq"];
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = Math.random().toString(36).slice(2, 7);
status.id = "bkw-seq-status-" + uid;
ta.setAttribute("aria-describedby", status.id);

const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const NAME = "[A-Za-z][\\w-]*";
const RX = {
  blank: /^\s*$/,
  comment: /^(\s*)(#.*)$/,
  title: /^(\s*)(title)(\s+)(.+)$/,
  part: new RegExp("^(\\s*)(participant|actor)(\\s+)(" + NAME + ")(\\s*)$"),
  note: new RegExp("^(\\s*)(note over)(\\s+)(" + NAME + ")(?:(\\s*,\\s*)(" + NAME + "))?(\\s*)(:)(\\s*)(.*)$"),
  msg: new RegExp("^(\\s*)(" + NAME + ")(\\s*)(-->|->)(\\s*)(" + NAME + ")(\\s*)(:)(\\s*)(.*)$")
};

function parse(text) {
  const lines = text.split("\n");
  const out = { title: "", parts: [], kinds: {}, items: [], errors: [], html: [] };
  const add = (n, kind) => { if (!out.kinds[n]) { out.parts.push(n); out.kinds[n] = kind || "participant"; } };
  lines.forEach((l, i) => {
    let m;
    const span = (cls, s) => (s ? '<span class="' + cls + '">' + esc(s) + "</span>" : "");
    if (RX.blank.test(l)) { out.html.push(esc(l)); return; }
    if ((m = l.match(RX.comment))) { out.html.push(esc(m[1]) + span("cm", m[2])); return; }
    if ((m = l.match(RX.title))) { out.title = m[4].trim(); out.html.push(esc(m[1]) + span("kw", m[2]) + esc(m[3]) + esc(m[4])); return; }
    if ((m = l.match(RX.part))) { add(m[4], m[2]); out.html.push(esc(m[1]) + span("kw", m[2]) + esc(m[3]) + span("nm", m[4]) + esc(m[5])); return; }
    if ((m = l.match(RX.note))) {
      add(m[4]); if (m[6]) add(m[6]);
      out.items.push({ t: "note", a: m[4], b: m[6] || m[4], text: m[10], line: i });
      out.html.push(esc(m[1]) + span("kw", m[2]) + esc(m[3]) + span("nm", m[4]) + (m[6] ? span("pc", m[5]) + span("nm", m[6]) : "") + esc(m[7]) + span("pc", m[8]) + esc(m[9]) + esc(m[10]));
      return;
    }
    if ((m = l.match(RX.msg))) {
      add(m[2]); add(m[6]);
      out.items.push({ t: "msg", a: m[2], b: m[6], ret: m[4] === "-->", text: m[10], line: i });
      out.html.push(esc(m[1]) + span("nm", m[2]) + esc(m[3]) + span("ar", m[4]) + esc(m[5]) + span("nm", m[6]) + esc(m[7]) + span("pc", m[8]) + esc(m[9]) + esc(m[10]));
      return;
    }
    out.errors.push(i);
    out.html.push('<span class="er">' + esc(l) + "</span>");
  });
  return out;
}

// ---------- drawing ----------
const COL = 150, PADX = 14, TOP = 14, BOX = 34;
let prevPos = new Map(), prevCols = new Map();
function draw(p, animate) {
  const n = Math.max(1, p.parts.length);
  const W = PADX * 2 + n * COL;
  const cx = (name) => PADX + COL / 2 + p.parts.indexOf(name) * COL;
  let y = TOP + BOX + 34;
  const body = [], pos = new Map(), cols = new Map();
  const seen = new Map();
  p.items.forEach((it) => {
    const base = it.t + "|" + it.a + "|" + it.b + "|" + it.text;
    const k = (seen.get(base) || 0) + 1;
    seen.set(base, k);
    const key = base + "#" + k;
    if (it.t === "note") {
      // a note is as wide as its text needs, centred over its lifelines and kept inside the drawing
      const mid = (cx(it.a) + cx(it.b)) / 2;
      const w = Math.max(Math.abs(cx(it.a) - cx(it.b)) + 112, it.text.length * 6.2 + 26);
      const x1 = Math.max(4, Math.min(W - 4 - w, mid - w / 2)), x2 = x1 + w;
      body.push({ key, y, x: x1, svg: '<g class="note" data-line="' + it.line + '" data-key="' + esc(key) + '"><rect x="' + x1 + '" y="' + (y - 13) + '" width="' + (x2 - x1) + '" height="26" rx="3"/><text x="' + (x1 + x2) / 2 + '" y="' + (y + 4) + '" text-anchor="middle">' + esc(it.text) + "</text></g>" });
      pos.set(key, { y, x: x1 });
      y += 40;
      return;
    }
    const x1 = cx(it.a), x2 = cx(it.b), cls = "msg" + (it.ret ? " ret" : "");
    let g;
    if (it.a === it.b) {
      const head = it.ret ? '<path class="head" d="M' + (x1 + 9) + " " + (y + 17) + "L" + (x1 + 2) + " " + (y + 22) + "L" + (x1 + 9) + " " + (y + 27) + '"/>' : '<path class="head" d="M' + (x1 + 1) + " " + (y + 22) + "L" + (x1 + 10) + " " + (y + 17) + "L" + (x1 + 10) + " " + (y + 27) + 'Z"/>';
      g = '<g class="' + cls + '" data-line="' + it.line + '" data-key="' + esc(key) + '"><path class="hit" d="M' + x1 + " " + y + "h38v22h-38" + '"/><path class="loop" d="M' + x1 + " " + y + "h38v22h-36" + '"/>' + head + '<text x="' + (x1 + 46) + '" y="' + (y + 15) + '">' + esc(it.text) + "</text></g>";
      pos.set(key, { y, x: x1 });
      body.push({ key, y, x: x1, svg: g, from: x1, dir: 1 });
      y += 52;
      return;
    }
    const dir = x2 > x1 ? 1 : -1;
    const hx = x2 - dir * 1;
    const head = it.ret
      ? '<path class="head" d="M' + (hx - dir * 9) + " " + (y - 5) + "L" + hx + " " + y + "L" + (hx - dir * 9) + " " + (y + 5) + '"/>'
      : '<path class="head" d="M' + hx + " " + y + "L" + (hx - dir * 10) + " " + (y - 5) + "L" + (hx - dir * 10) + " " + (y + 5) + 'Z"/>';
    g = '<g class="' + cls + '" data-line="' + it.line + '" data-key="' + esc(key) + '" data-dir="' + dir + '"><line class="hit" x1="' + x1 + '" y1="' + y + '" x2="' + x2 + '" y2="' + y + '"/><line x1="' + x1 + '" y1="' + y + '" x2="' + (x2 - dir * 2) + '" y2="' + y + '"/>' + head + '<text x="' + (x1 + x2) / 2 + '" y="' + (y - 7) + '" text-anchor="middle">' + esc(it.text) + "</text></g>";
    pos.set(key, { y, x: Math.min(x1, x2), span: Math.abs(x2 - x1) });
    body.push({ key, y, svg: g });
    y += 40;
  });
  const bottom = y + 2;
  const H = bottom + BOX + TOP;
  const partSvg = p.parts.map((name, i) => {
    const x = PADX + COL / 2 + i * COL;
    cols.set(name, x);
    const actor = p.kinds[name] === "actor";
    const box = (yy) => actor
      ? '<g class="actor"><circle cx="' + x + '" cy="' + (yy + 7) + '" r="5"/><path d="M' + x + " " + (yy + 12) + "v9M" + (x - 7) + " " + (yy + 15) + "h14M" + x + " " + (yy + 21) + "l-5 7M" + x + " " + (yy + 21) + 'l5 7"/></g><text class="pname" x="' + (x + 12) + '" y="' + (yy + 22) + '">' + esc(name) + "</text>"
      : '<rect class="pbox" x="' + (x - 54) + '" y="' + yy + '" width="108" height="' + BOX + '" rx="7"/><text class="pname" x="' + x + '" y="' + (yy + 21.5) + '" text-anchor="middle">' + esc(name) + "</text>";
    return '<g class="part" data-key="p|' + esc(name) + '"><line class="life" x1="' + x + '" y1="' + (TOP + BOX) + '" x2="' + x + '" y2="' + bottom + '"/>' + box(TOP) + box(bottom) + "</g>";
  }).join("");
  svg.setAttribute("viewBox", "0 0 " + W + " " + H);
  svg.style.setProperty("--minw", Math.max(0, n * 118) + "px");
  svg.innerHTML = partSvg + body.map((b) => b.svg).join("");

  // motion: participants and messages that already existed glide; new ones draw in
  if (animate && !reduce) {
    let k = 0;
    svg.querySelectorAll(".part").forEach((g) => {
      const name = g.dataset.key.slice(2), was = prevCols.get(name), now = cols.get(name);
      if (was === undefined) g.animate([{ opacity: 0, transform: "translateY(-6px)" }, { opacity: 1, transform: "none" }], { duration: 380, easing: "cubic-bezier(.2,.8,.2,1)" });
      else if (was !== now) g.animate([{ transform: "translateX(" + (was - now) + "px)" }, { transform: "none" }], { duration: 560, easing: "cubic-bezier(.2,.9,.25,1)" });
    });
    svg.querySelectorAll("[data-key]:not(.part)").forEach((g) => {
      const key = g.dataset.key, was = prevPos.get(key), now = pos.get(key);
      if (was && now && was.x === now.x && was.span === now.span) {
        if (was.y !== now.y) g.animate([{ transform: "translateY(" + (was.y - now.y) + "px)" }, { transform: "none" }], { duration: 520, easing: "cubic-bezier(.2,.9,.25,1)" });
        return;
      }
      const d = k++ * 70;
      const ln = g.querySelector("line:not(.hit), path.loop, rect");
      if (ln) {
        const dir = +(g.dataset.dir || 1);
        ln.style.transformOrigin = dir > 0 ? "left center" : "right center";
        ln.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], { duration: 420, delay: d, easing: "cubic-bezier(.3,.7,.2,1)", fill: "backwards" });
      }
      g.querySelectorAll(".head, text").forEach((el) => el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 260, delay: d + 260, fill: "backwards" }));
    });
  }
  prevPos = pos;
  prevCols = cols;
}

// ---------- editor plumbing ----------
let parsed = null, curLine = -1;
function render(animate) {
  const text = ta.value;
  parsed = parse(text);
  const lines = text.split("\n");
  hl.innerHTML = parsed.html.map((h, i) => '<span class="ln" data-n="' + i + '">' + (h || " ") + "</span>").join("\n") + "\n";
  gut.innerHTML = lines.map((_, i) => '<li class="' + (parsed.errors.includes(i) ? "is-err" : "") + '">' + (i + 1) + "</li>").join("");
  ta.style.height = (lines.length * parseFloat(getComputedStyle(root.querySelector(".bkw-seq__code")).getPropertyValue("--lh")) + 24 + 10) + "px";
  const msgs = parsed.items.filter((i) => i.t === "msg").length, notes = parsed.items.length - msgs;
  meta.textContent = parsed.parts.length + " participants · " + msgs + " messages" + (notes ? " · " + notes + (notes > 1 ? " notes" : " note") : "");
  dtitle.textContent = parsed.title || "Untitled diagram";
  if (parsed.errors.length) {
    status.classList.add("is-err");
    status.textContent = "Line " + (parsed.errors[0] + 1) + ": expected “A -> B: message”" + (parsed.errors.length > 1 ? " (+" + (parsed.errors.length - 1) + " more)" : "") + " — drawing the rest";
  } else {
    status.classList.remove("is-err");
    status.textContent = "Parsed " + lines.length + " lines · diagram up to date";
  }
  draw(parsed, animate);
  curLine = -1;
  syncCaret();
}
function setHot(line, on) {
  const ln = hl.querySelector('.ln[data-n="' + line + '"]');
  if (ln) ln.classList.toggle("is-hot", on);
  svg.querySelectorAll('[data-line="' + line + '"]').forEach((g) => g.classList.toggle("is-hot", on));
}
function syncCaret() {
  const line = ta.value.slice(0, ta.selectionStart).split("\n").length - 1;
  const focused = document.activeElement === ta;
  const want = focused ? line : -1;
  if (want === curLine) return;
  if (curLine >= 0) {
    setHot(curLine, false);
    const ln = hl.querySelector('.ln[data-n="' + curLine + '"]'); if (ln) ln.classList.remove("is-cur");
    const g = gut.children[curLine]; if (g) g.classList.remove("is-cur");
  }
  curLine = want;
  if (curLine >= 0) {
    svg.querySelectorAll('[data-line="' + curLine + '"]').forEach((g) => g.classList.add("is-hot"));
    const ln = hl.querySelector('.ln[data-n="' + curLine + '"]'); if (ln) ln.classList.add("is-cur");
    const g = gut.children[curLine]; if (g) g.classList.add("is-cur");
  }
}

let t = 0;
ta.addEventListener("input", () => {
  root.classList.add("is-edited");
  exBtns.forEach((b) => b.setAttribute("aria-pressed", "false"));
  clearTimeout(t);
  t = setTimeout(() => { if (root.isConnected) render(true); }, 140);
});
ta.addEventListener("scroll", () => { hl.scrollLeft = ta.scrollLeft; });
["keyup", "click", "select", "focus", "blur"].forEach((ev) => ta.addEventListener(ev, syncCaret));

// hovering an arrow lights its source line (and focusing the editor follows the caret)
let hover = -1;
svg.addEventListener("pointerover", (e) => {
  const g = e.target.closest("[data-line]");
  const n = g ? +g.dataset.line : -1;
  if (n === hover) return;
  if (hover >= 0 && hover !== curLine) setHot(hover, false);
  hover = n;
  if (hover >= 0) setHot(hover, true);
});
svg.addEventListener("pointerleave", () => { if (hover >= 0 && hover !== curLine) setHot(hover, false); hover = -1; });
svg.addEventListener("click", (e) => {
  const g = e.target.closest("[data-line]");
  if (!g) return;
  const n = +g.dataset.line;
  const lines = ta.value.split("\n");
  let start = 0;
  for (let i = 0; i < n; i++) start += lines[i].length + 1;
  ta.focus({ preventScroll: true });
  ta.setSelectionRange(start, start + lines[n].length);
  syncCaret();
});

exBtns.forEach((b, i) => b.addEventListener("click", () => {
  exBtns.forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
  ta.value = sources[i];
  file.textContent = FILES[i];
  root.classList.remove("is-edited");
  prevPos = new Map(); prevCols = new Map();
  render(true);
}));

render(false);

