/* Tessera — a material card viewer. Re-theme the room with --bkw-card-bg, -ink, -gold;
   each finish is a set of registered pigments, so switching finishes cross-fades. */
@property --bkw-card-base { syntax: "<color>"; inherits: true; initial-value: oklch(0.26 0.01 260); }
@property --bkw-card-hi { syntax: "<color>"; inherits: true; initial-value: oklch(0.46 0.01 260); }
@property --bkw-card-lo { syntax: "<color>"; inherits: true; initial-value: oklch(0.14 0.01 260); }
@property --bkw-card-etch { syntax: "<color>"; inherits: true; initial-value: oklch(0.78 0.03 85); }
@property --bkw-card-brush { syntax: "<number>"; inherits: true; initial-value: 1; }
@property --bkw-card-wood { syntax: "<number>"; inherits: true; initial-value: 0; }

.bkw-card {
  --bkw-card-bg: oklch(0.165 0.008 70);
  --bkw-card-ink: oklch(0.93 0.02 85);
  --bkw-card-gold: oklch(0.8 0.1 82);
  --bkw-card-mute: color-mix(in oklch, var(--bkw-card-ink) 58%, var(--bkw-card-bg));
  --bkw-card-line: color-mix(in oklch, var(--bkw-card-ink) 14%, transparent);
  --bkw-card-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --bkw-card-flip: linear(0, 0.035, 0.119, 0.232, 0.357, 0.486, 0.604, 0.71, 0.801, 0.877, 0.936, 0.98, 1.012, 1.033, 1.045, 1.051, 1.052, 1.049, 1.044, 1.038, 1.031, 1.025, 1.019, 1.013, 1.009, 1.005, 1.003, 1, 0.999, 0.998, 0.998, 0.997, 0.997, 0.998, 0.998, 0.998, 1);
  --bkw-card-soft: linear(0, 0.024, 0.082, 0.159, 0.247, 0.337, 0.427, 0.509, 0.587, 0.655, 0.717, 0.769, 0.815, 0.853, 0.885, 0.911, 0.933, 0.949, 0.963, 0.974, 0.982, 0.989, 0.993, 0.997, 0.999, 1.001, 1.002, 1.003, 1.003, 1.003, 1.003, 1.003, 1.003, 1.002, 1.002, 1.002, 1);

  /* titanium by default */
  --bkw-card-base: oklch(0.27 0.008 260);
  --bkw-card-hi: oklch(0.5 0.01 260);
  --bkw-card-lo: oklch(0.15 0.008 260);
  --bkw-card-etch: oklch(0.8 0.025 85);
  --bkw-card-brush: 1;
  --bkw-card-wood: 0;
  transition: --bkw-card-base .7s ease, --bkw-card-hi .7s ease, --bkw-card-lo .7s ease, --bkw-card-etch .7s ease, --bkw-card-brush .7s ease, --bkw-card-wood .7s ease;

  container-type: inline-size;
  container-name: bkw-card;
  position: relative; box-sizing: border-box; width: 100%; overflow: hidden; border-radius: 24px;
  background:
    radial-gradient(60% 70% at 72% 45%, color-mix(in oklch, var(--bkw-card-gold) 10%, transparent), transparent 70%),
    var(--bkw-card-bg);
  color: var(--bkw-card-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :focus-visible { outline: 1.5px solid var(--bkw-card-gold); outline-offset: 4px; }
}
.bkw-card:has([value="steel"]:checked) { --bkw-card-base: oklch(0.74 0.008 250); --bkw-card-hi: oklch(0.93 0.005 250); --bkw-card-lo: oklch(0.52 0.01 250); --bkw-card-etch: oklch(0.36 0.01 250); --bkw-card-brush: 1; --bkw-card-wood: 0; }
.bkw-card:has([value="walnut"]:checked) { --bkw-card-base: oklch(0.43 0.07 52); --bkw-card-hi: oklch(0.56 0.08 58); --bkw-card-lo: oklch(0.3 0.055 45); --bkw-card-etch: oklch(0.22 0.04 45); --bkw-card-brush: 0; --bkw-card-wood: 1; }
.bkw-card:has([value="gold"]:checked) { --bkw-card-base: oklch(0.8 0.075 82); --bkw-card-hi: oklch(0.94 0.05 90); --bkw-card-lo: oklch(0.6 0.08 72); --bkw-card-etch: oklch(0.42 0.06 65); --bkw-card-brush: 1; --bkw-card-wood: 0; }

.bkw-card__in { display: grid; grid-template-columns: minmax(0, 1fr); grid-template-areas: "copy" "stage"; gap: 18px; padding: clamp(20px, 4.4cqi, 56px); }

/* ---------- copy ---------- */
.bkw-card__copy { grid-area: copy; min-width: 0; }
.bkw-card__brand {
  margin: 0; display: inline-flex; align-items: center; gap: 10px; font: 600 12.5px/1 system-ui, sans-serif; letter-spacing: .32em; text-transform: uppercase;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkw-card-gold); stroke-width: 1.4; stroke-linecap: round; }
}
.bkw-card__title { margin: 26px 0 0; max-width: 14ch; font: 400 clamp(2.1rem, 1.2rem + 3.6cqi, 3.6rem)/1.02 var(--bkw-card-serif); letter-spacing: -.02em; text-wrap: balance; }
.bkw-card__lede { margin: 18px 0 0; max-width: 42ch; font-size: clamp(14.5px, 13.8px + .25cqi, 16.5px); line-height: 1.65; color: var(--bkw-card-mute); text-wrap: pretty; }

.bkw-card__fin {
  margin: 26px 0 0; padding: 0; border: 0; min-width: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px;
  & legend { padding: 0; margin-bottom: 10px; font-size: 11px; font-weight: 600; letter-spacing: .24em; text-transform: uppercase; color: var(--bkw-card-mute); }
}
.bkw-card__sw {
  position: relative; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 12px; cursor: pointer;
  border: 1px solid var(--bkw-card-line); transition: border-color .3s, background-color .3s;
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & i { width: 22px; height: 22px; border-radius: 50%; box-shadow: inset 0 0 0 1px color-mix(in oklch, white 25%, transparent), 0 2px 6px black; }
  & span { font-size: 13.5px; }
  & b { font: 500 12.5px/1 system-ui, sans-serif; color: var(--bkw-card-mute); font-variant-numeric: tabular-nums; }
  &:hover { border-color: color-mix(in oklch, var(--bkw-card-ink) 30%, transparent); }
  &:has(:checked) { border-color: var(--bkw-card-gold); background: color-mix(in oklch, var(--bkw-card-gold) 7%, transparent); }
  &:has(:focus-visible) { outline: 1.5px solid var(--bkw-card-gold); outline-offset: 3px; }
}
.bkw-card__sw--steel i { background: linear-gradient(135deg, oklch(0.93 0.005 250), oklch(0.6 0.01 250) 60%, oklch(0.85 0.005 250)); }
.bkw-card__sw--titan i { background: linear-gradient(135deg, oklch(0.5 0.01 260), oklch(0.18 0.008 260) 60%, oklch(0.38 0.01 260)); }
.bkw-card__sw--walnut i { background: repeating-linear-gradient(100deg, oklch(0.47 0.075 52) 0 3px, oklch(0.34 0.06 45) 3px 5px); }
.bkw-card__sw--gold i { background: linear-gradient(135deg, oklch(0.95 0.05 90), oklch(0.66 0.09 75) 60%, oklch(0.88 0.06 85)); }

.bkw-card__buy { margin-top: 24px; display: flex; flex-wrap: wrap; align-items: center; gap: 14px 22px; }
.bkw-card__cta {
  padding: 14px 22px; border: 0; border-radius: 999px; cursor: pointer; font-family: inherit; font-weight: 600; font-size: 14.5px; letter-spacing: .02em; color: var(--bkw-card-bg); background: var(--bkw-card-ink);
  transition: background-color .3s, translate .4s var(--bkw-card-soft);
  & span { font-variant-numeric: tabular-nums; }
  &:hover { background: var(--bkw-card-gold); translate: 0 -2px; }
}
.bkw-card__spec { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 12.5px; color: var(--bkw-card-mute);
  & li + li::before { content: ""; display: inline-block; width: 3px; height: 3px; border-radius: 50%; margin: 0 10px 2px -8px; background: var(--bkw-card-gold); } }

/* the bag line under the button; while the bag is empty it stays in the tree (as a live region) but out of sight */
.bkw-card__bag {
  flex: 1 1 100%; max-width: 460px; display: flex; align-items: center; gap: 10px; padding: 9px 9px 9px 13px; border-radius: 14px;
  border: 1px solid color-mix(in oklch, var(--bkw-card-gold) 45%, transparent); background: color-mix(in oklch, var(--bkw-card-gold) 8%, transparent);
  font-size: 13.5px;
  & svg { flex: none; width: 20px; height: 20px; fill: none; stroke: var(--bkw-card-gold); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & p { flex: 1; min-width: 0; margin: 0; line-height: 1.4; }
  & p b { font-weight: 600; }
  &:not(.is-on) { position: absolute; width: 1px; height: 1px; padding: 0; border: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}
.bkw-card__undo {
  flex: none; padding: 7px 12px; border-radius: 999px; border: 1px solid var(--bkw-card-line); background: transparent; color: var(--bkw-card-ink);
  font: 500 12.5px/1 system-ui, sans-serif; cursor: pointer; transition: border-color .3s;
  &:hover { border-color: var(--bkw-card-gold); }
  &[hidden] { display: none; }
}

/* ---------- stage + card ---------- */
.bkw-card__stage {
  grid-area: stage; position: relative; min-width: 0; height: 360px; display: grid; place-items: center;
  perspective: 1100px; touch-action: pan-y; cursor: grab; user-select: none; -webkit-user-select: none;
  &.is-drag { cursor: grabbing; }
}
.bkw-card__tilt {
  --rx: 0; --ry: 0;
  width: min(380px, 86cqi); aspect-ratio: 85.6 / 54; transform-style: preserve-3d;
  transform: rotateX(calc(var(--rx) * 1deg)) rotateY(calc(var(--ry) * 1deg));
  translate: 0 -16px;
}
.bkw-card__obj {
  position: relative; width: 100%; height: 100%; transform-style: preserve-3d; border-radius: 4.2% / 6.6%; outline-offset: 10px;
  transform: rotateY(calc(var(--flip, 0) * 180deg));
  transition: transform 1.1s var(--bkw-card-flip);
}
.bkw-card__obj[aria-pressed="true"] { --flip: 1; }
.bkw-card__slice {
  position: absolute; inset: 0; border-radius: inherit; background: color-mix(in oklch, var(--bkw-card-lo), black 20%);
  transform: translateZ(calc(var(--z) * 1px));
}
.bkw-card__face {
  position: absolute; inset: 0; border-radius: inherit; overflow: hidden; backface-visibility: hidden; -webkit-backface-visibility: hidden;
  background: var(--bkw-card-base); color: var(--bkw-card-etch);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--bkw-card-hi) 70%, transparent), inset 0 -1px 0 color-mix(in oklch, var(--bkw-card-lo) 60%, transparent);
}
.bkw-card__face--back { transform: translateZ(-2.4px) rotateY(180deg); }

/* the material: brushed lines + anisotropic streak, or walnut grain; cross-faded by registered numbers */
.bkw-card__mat {
  position: absolute; inset: 0;
  &::before, &::after { content: ""; position: absolute; inset: 0; }
  &::before {
    opacity: var(--bkw-card-brush);
    background:
      linear-gradient(90deg, transparent calc(30% + var(--ry) * 1.6%), color-mix(in oklch, var(--bkw-card-hi) 75%, transparent) calc(45% + var(--ry) * 1.6%), transparent calc(62% + var(--ry) * 1.6%)),
      repeating-linear-gradient(0deg, color-mix(in oklch, var(--bkw-card-hi) 18%, transparent) 0 1px, transparent 1px 2px, color-mix(in oklch, var(--bkw-card-lo) 22%, transparent) 2px 3px, transparent 3px 5px),
      linear-gradient(calc(160deg + var(--rx) * 2deg), var(--bkw-card-lo), var(--bkw-card-base) 45%, var(--bkw-card-hi) 75%, var(--bkw-card-base));
  }
  &::after {
    opacity: var(--bkw-card-wood);
    background:
      repeating-radial-gradient(ellipse 320% 46% at 22% 150%, transparent 0 4px, color-mix(in oklch, var(--bkw-card-lo) 75%, transparent) 5px 6px, transparent 7px 12px),
      repeating-radial-gradient(ellipse 280% 60% at 88% -70%, transparent 0 6px, color-mix(in oklch, var(--bkw-card-lo) 45%, transparent) 7px 8px, transparent 9px 15px),
      repeating-linear-gradient(1.5deg, color-mix(in oklch, var(--bkw-card-hi) 16%, transparent) 0 1px, transparent 1px 3px),
      linear-gradient(calc(120deg + var(--ry) * 1.5deg), var(--bkw-card-hi), var(--bkw-card-base) 40%, var(--bkw-card-lo));
  }
}
.bkw-card__glare {
  position: absolute; inset: 0; pointer-events: none; mix-blend-mode: soft-light;
  background: radial-gradient(70% 90% at calc(50% + var(--ry) * 3%) calc(40% - var(--rx) * 3%), color-mix(in oklch, white 80%, transparent), transparent 60%);
}
/* engraving: dark cut with a 1px lit lower edge */
.bkw-card__face :is(b, span:not(.bkw-card__mat, .bkw-card__glare), code) { text-shadow: 0 1px 0 color-mix(in oklch, var(--bkw-card-hi) 60%, transparent), 0 -.5px 0 color-mix(in oklch, black 30%, transparent); }
.bkw-card__nfc { position: absolute; top: 9%; right: 6.5%; width: 9%; fill: none; stroke: var(--bkw-card-etch); stroke-width: 1.6; stroke-linecap: round; opacity: .9; }
.bkw-card__logo { position: absolute; top: 9%; left: 6.5%; width: 8.5%; fill: none; stroke: var(--bkw-card-etch); stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
.bkw-card__who { position: absolute; left: 6.5%; bottom: 10%; display: grid; gap: .1em; container-type: inline-size; width: 70%;
  & b { font: 400 7.6cqi/1.1 var(--bkw-card-serif); letter-spacing: -.01em; white-space: nowrap; }
  & span { font-size: 3.9cqi; letter-spacing: .18em; text-transform: uppercase; }
  & .bkw-card__co { margin-top: .5em; font-weight: 600; } }
.bkw-card__mark { position: absolute; right: 6.5%; bottom: 10%; font-size: 9px; letter-spacing: .38em; font-weight: 600; opacity: .75; }
.bkw-card__qr { position: absolute; left: 6.5%; top: 50%; translate: 0 -50%; width: 34%; border-radius: 6px;
  & rect { fill: color-mix(in oklch, var(--bkw-card-hi) 35%, transparent); } & path { fill: var(--bkw-card-etch); } }
.bkw-card__tap { position: absolute; left: 47%; right: 6%; top: 50%; translate: 0 -50%; display: grid; gap: 5px; container-type: inline-size;
  & b { font: 400 13cqi/1.05 var(--bkw-card-serif); }
  & span { font-size: 6.8cqi; line-height: 1.35; }
  & code { margin-top: 6px; font: 600 6.6cqi/1 ui-monospace, Menlo, monospace; letter-spacing: .02em; } }

.bkw-card__shadow {
  position: absolute; left: 50%; top: 50%; width: min(330px, 74cqi); height: 46px; border-radius: 50%;
  translate: calc(-50% - var(--sy, 0) * 1px) calc(min(120px, 26cqi) + var(--sx, 0) * .6px);
  background: radial-gradient(closest-side, color-mix(in oklch, black 75%, transparent), transparent);
  filter: blur(10px);
}
.bkw-card__ctrl { position: absolute; left: 0; right: 0; bottom: 0; display: flex; align-items: center; justify-content: center; gap: 16px; flex-wrap: wrap; }
.bkw-card__flip {
  display: inline-flex; align-items: center; gap: 8px; padding: 9px 14px; border-radius: 999px; border: 1px solid var(--bkw-card-line); cursor: pointer;
  background: transparent; color: var(--bkw-card-ink); font: 500 13px/1 system-ui, sans-serif;
  transition: border-color .3s, background-color .3s;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: rotate .8s var(--bkw-card-flip); }
  &:hover { border-color: var(--bkw-card-gold); }
  &[aria-pressed="true"] svg { rotate: 180deg; }
}
.bkw-card__hint { margin: 0; font-size: 12px; letter-spacing: .06em; color: var(--bkw-card-mute); }

@container bkw-card (min-width: 860px) {
  .bkw-card__in { grid-template-columns: minmax(300px, .9fr) minmax(0, 1.1fr); grid-template-areas: "copy stage"; gap: 40px; align-items: center; }
  .bkw-card__stage { height: 520px; }
  .bkw-card__tilt { width: min(440px, 88%); }
  .bkw-card__shadow { width: min(380px, 80%); translate: calc(-50% - var(--sy, 0) * 1px) calc(150px + var(--sx, 0) * .6px); }
}
@container bkw-card (max-width: 419.98px) {
  .bkw-card__fin { grid-template-columns: minmax(0, 1fr); }
  .bkw-card__stage { height: 320px; }
  .bkw-card__hint { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkw-card { transition: none; }
  .bkw-card .bkw-card__obj { transition: transform .01s linear; }
  .bkw-card .bkw-card__flip svg, .bkw-card .bkw-card__cta { transition: none; }
}

