// Tessera card. Tilt is a damped spring toward a target (pointer, keys, or the rest pose);
// the loop runs only while the spring is moving and stops itself when it settles.
const stage = root.querySelector(".bkw-card__stage");
const tilt = root.querySelector(".bkw-card__tilt");
const obj = root.querySelector(".bkw-card__obj");
const shadow = root.querySelector(".bkw-card__shadow");
const flipBtn = root.querySelector(".bkw-card__flip");
const flipLabel = flipBtn.querySelector("span");
const price = root.querySelector(".bkw-card__price");
const radios = Array.from(root.querySelectorAll(".bkw-card__fin input"));
const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = Math.random().toString(36).slice(2, 7);
radios.forEach((r) => { r.name = "bkw-card-finish-" + uid; });

const REST = { x: 9, y: -16 };
const s = { x: 0, y: 0, vx: 0, vy: 0, tx: REST.x, ty: REST.y };
let raf = 0, last = 0;
function write() {
  // the faces inherit --rx/--ry, so the streak, grain and glare follow the same tilt
  tilt.style.setProperty("--rx", s.x.toFixed(2));
  tilt.style.setProperty("--ry", s.y.toFixed(2));
  shadow.style.setProperty("--sx", s.x.toFixed(2));
  shadow.style.setProperty("--sy", s.y.toFixed(2));
}
function step(now) {
  if (!root.isConnected) return;
  const dt = Math.min(0.032, (now - (last || now)) / 1000 || 0.016);
  last = now;
  const K = 90, C = 13;
  s.vx += ((s.tx - s.x) * K - s.vx * C) * dt;
  s.vy += ((s.ty - s.y) * K - s.vy * C) * dt;
  s.x += s.vx * dt;
  s.y += s.vy * dt;
  write();
  const moving = Math.abs(s.tx - s.x) + Math.abs(s.ty - s.y) + Math.abs(s.vx) + Math.abs(s.vy) > 0.02;
  if (moving && !document.hidden) raf = requestAnimationFrame(step);
  else { raf = 0; last = 0; }
}
function kick() {
  if (reduce) { s.x = s.tx; s.y = s.ty; write(); return; }
  if (!raf) raf = requestAnimationFrame(step);
}
function aim(tx, ty) { s.tx = Math.max(-24, Math.min(24, tx)); s.ty = Math.max(-30, Math.min(30, ty)); kick(); }

// pointer: hover aims the card at the cursor, a drag tilts it further; leaving returns to rest
let drag = null;
stage.addEventListener("pointermove", (e) => {
  if (e.pointerType === "touch" && !drag) return;
  const r = tilt.getBoundingClientRect();
  const nx = (e.clientX - (r.left + r.width / 2)) / (r.width / 2);
  const ny = (e.clientY - (r.top + r.height / 2)) / (r.height / 2);
  if (drag) aim(drag.x - (e.clientY - drag.cy) * 0.25, drag.y + (e.clientX - drag.cx) * 0.25);
  else aim(-ny * 14, nx * 18);
});
stage.addEventListener("pointerdown", (e) => {
  if (e.button !== 0 || e.target.closest("button")) return;
  drag = { cx: e.clientX, cy: e.clientY, x: s.tx, y: s.ty, t: performance.now() };
  stage.setPointerCapture(e.pointerId);
  stage.classList.add("is-drag");
});
const release = (e) => {
  if (!drag) return;
  const tap = performance.now() - drag.t < 220 && Math.hypot(e.clientX - drag.cx, e.clientY - drag.cy) < 6;
  drag = null;
  stage.classList.remove("is-drag");
  if (tap && e.target.closest(".bkw-card__obj")) flip();
  aim(REST.x, REST.y);
};
stage.addEventListener("pointerup", release);
stage.addEventListener("pointercancel", release);
stage.addEventListener("pointerleave", () => { if (!drag) aim(REST.x, REST.y); });

function flip() {
  const on = obj.getAttribute("aria-pressed") !== "true";
  obj.setAttribute("aria-pressed", String(on));
  flipBtn.setAttribute("aria-pressed", String(on));
  obj.setAttribute("aria-label", "Tessera card, " + (on ? "back" : "front") + ". Press Enter to flip; arrow keys tilt.");
  flipLabel.textContent = on ? "See the front" : "See the back";
  // a flip throws the card a little, and the spring catches it
  s.vy += on ? -60 : 60;
  kick();
}
flipBtn.setAttribute("aria-pressed", "false");
flipBtn.addEventListener("click", flip);
obj.addEventListener("keydown", (e) => {
  if (e.key === "Enter" || e.key === " ") { e.preventDefault(); flip(); return; }
  const d = { ArrowUp: [5, 0], ArrowDown: [-5, 0], ArrowLeft: [0, -6], ArrowRight: [0, 6] }[e.key];
  if (d) { e.preventDefault(); aim(s.tx + d[0], s.ty + d[1]); }
  if (e.key === "Escape" || e.key === "Home") { e.preventDefault(); aim(REST.x, REST.y); }
});
obj.addEventListener("blur", () => aim(REST.x, REST.y));

radios.forEach((r) => r.addEventListener("change", () => {
  if (!r.checked) return;
  price.textContent = "€" + r.dataset.price;
  s.vy += 26;
  kick();
}));

// ordering adds the chosen finish to a bag; the line under the button keeps the running total
const verb = root.querySelector(".bkw-card__verb");
const cta = root.querySelector(".bkw-card__cta");
const bagEl = root.querySelector(".bkw-card__bag");
const bagMsg = bagEl.querySelector("p");
const undo = root.querySelector(".bkw-card__undo");
const bag = [];
let clearTimer = 0;
function showBag(text) {
  clearTimeout(clearTimer);
  const total = bag.reduce((n, x) => n + x.price, 0);
  bagMsg.replaceChildren();
  const b = document.createElement("b");
  b.textContent = text;
  bagMsg.append(b, bag.length ? " \u00b7 " + bag.length + (bag.length > 1 ? " cards" : " card") + " in your bag, \u20ac" + total : ". Your bag is empty.");
  bagEl.classList.add("is-on");
  undo.hidden = !bag.length;
  verb.textContent = bag.length ? "Add another" : "Order yours";
  if (!reduce) bagEl.animate([{ opacity: 0.4, transform: "translateY(-4px)" }, { opacity: 1, transform: "none" }], { duration: 380, easing: "cubic-bezier(.2, .8, .2, 1)" });
  if (!bag.length) clearTimer = setTimeout(() => { if (root.isConnected && !bag.length) { bagEl.classList.remove("is-on"); bagMsg.textContent = ""; } }, 2600);
}
cta.addEventListener("click", () => {
  const r = radios.find((x) => x.checked) || radios[0];
  const name = r.parentElement.querySelector("span").textContent;
  bag.push({ name, price: Number(r.dataset.price) });
  showBag(name + " added");
});
undo.addEventListener("click", () => {
  const gone = bag.pop();
  if (!gone) return;
  showBag(gone.name + " removed");
  if (!bag.length) cta.focus();
});

// settle into the rest pose the first time the card is seen
const io = new IntersectionObserver((ents) => {
  if (!root.isConnected) { io.disconnect(); return; }
  if (ents.some((x) => x.isIntersecting)) { io.disconnect(); s.y = -34; s.x = 2; kick(); }
}, { threshold: 0.3 });
write();
io.observe(stage);
